INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('childrens-homes-quality-standards', 'guides', 'Understanding the Children\'s Homes Quality Standards', 'What each of the nine quality standards in the Children\'s Homes (England) Regulations 2015 means for residential staff on an ordinary shift.', 'The nine quality standards in regulations 6 to 14 of the Children\'s Homes (England) Regulations 2015 describe the outcomes every children\'s home must deliver. This guide explains each standard in plain English and shows what it looks like in practice on shift.', '["Children\'s Homes (England) Regulations 2015","Care Standards Act 2000","Guide to the Children\'s Homes Regulations including the quality standards (2015)","Children Act 1989"]', '<p>If you work in a children\'s home in England, the Children\'s Homes (England) Regulations 2015 are the legal foundation of your job. Regulations 6 to 14 set out nine quality standards. They are deliberately written as outcomes for children, not as tick-lists for adults, and Ofsted inspects against them under the social care common inspection framework (SCCIF). The Guide to the Children\'s Homes Regulations including the quality standards, published in April 2015, explains how each standard should be interpreted, and every member of staff should have read it.</p><p>The standards are not paperwork that lives in the office. They describe what a good shift looks like. Here is each one, and what it means when you are the adult in the building.</p><h2>Regulation 6: The quality and purpose of care standard</h2><p>Children must receive care that meets their individual needs, in a home that is nurturing, safe and well maintained, and that matches its statement of purpose. On shift this means knowing what your home says it offers and who it is for, because you should be able to explain how the care you give reflects it. It also covers the physical environment: a scruffy, institutional building tells children what you think of them. Broken furniture reported and fixed quickly, bedrooms personalised, and a home that feels like a home are all Regulation 6 matters.</p><h2>Regulation 7: The children\'s views, wishes and feelings standard</h2><p>Children must be consulted and their views taken seriously in day-to-day decisions and in their plans, and they must know how to complain and be supported to do so. In practice: house meetings that actually change things, asking children about menus, activities, decoration and rules, recording their views in their own words, and never treating a complaint as an inconvenience or disloyalty. A child who complains is using the system exactly as intended.</p><h2>Regulation 8: The education standard</h2><p>Children must be supported to make measurable progress in education and to attend consistently. On shift this means school runs done reliably and on time, homework supported in the evening, attendance problems chased and understood rather than shrugged at, liaison with schools and virtual school heads, and celebrating educational achievement as loudly as anything else. If a child is out of education, the home should be pushing hard, every week, for provision.</p><h2>Regulation 9: The enjoyment and achievement standard</h2><p>Children must be able to develop interests, take part in activities and enjoy their childhood. This is the standard that says fun is a professional duty. Clubs, sport, hobbies, birthdays done properly, trips, and ordinary experiences such as cinema visits and cooking together all count. The test is whether this child, with their interests, is getting a rich life, not whether the home once bought a games console.</p><h2>Regulation 10: The health and well-being standard</h2><p>Children\'s physical, emotional and mental health needs must be met, including registration with GPs and dentists, attendance at appointments, and access to specialist and therapeutic support. On shift: medication given and recorded accurately, health appointments prioritised like school, emotional well-being noticed and acted on, and healthy food and routines modelled rather than lectured. Staff should know each child\'s health plan, allergies and current concerns without needing to look them up mid-crisis.</p><h2>Regulation 11: The positive relationships standard</h2><p>Children must be helped to build positive relationships with staff, other children, family and friends, and behaviour must be managed through relationships, with restraint used only when necessary and proportionate (see also Regulation 20 on restraint). This is the heart of residential work: warm, consistent, boundaried relationships; contact with family supported in line with each child\'s plan; conflict between children handled fairly; and consequences that are restorative and proportionate rather than punitive. Blanket sanctions and group punishments sit badly with this standard.</p><h2>Regulation 12: The protection of children standard</h2><p>Children must be protected from harm, and the home must assess and manage risk without wrapping children in cotton wool. On shift this means knowing each child\'s risk assessment and safety plan, following missing-from-home procedures precisely, understanding exploitation risks including criminal and sexual exploitation and county lines, supervising in line with plans, and reporting concerns immediately through safeguarding procedures. It also means enabling safe risk-taking, because children learn by doing, and a home that never lets a child out of sight is failing this standard in a different way.</p><h2>Regulation 13: The leadership and management standard</h2><p>The registered person must lead a home with high ambitions, a workforce that is skilled, supported and supervised, and a culture of continuous improvement. Frontline staff feel this standard through supervision that actually happens, team meetings that discuss children rather than only rotas, training that is completed and used, and a manager who knows the children well. If you are asked at inspection whether you feel supported and how the manager monitors quality, this is the standard behind the question.</p><h2>Regulation 14: The care planning standard</h2><p>Children must only be admitted when the home can meet their needs alongside those of children already living there, and their care must follow up-to-date plans, with proper preparation for moving in and moving on. On shift this means impact risk assessments before admissions, keyworker sessions that connect to the child\'s relevant plans, contributions to looked-after child reviews, and transitions planned weeks ahead rather than announced in a bin bag on the day.</p><h2>How the standards fit together</h2><p>Each standard has the same structure: an outcome for children, followed by a list of things the registered person must ensure. Ofsted does not inspect them as nine separate boxes; inspectors look at the experiences and progress of children and trace them back to the standards. That is why the best preparation for inspection is not memorising regulation numbers but being able to talk, child by child, about needs, plans, progress and how you keep them safe.</p><table><tr><th>Regulation</th><th>Standard</th></tr><tr><td>6</td><td>Quality and purpose of care</td></tr><tr><td>7</td><td>Children\'s views, wishes and feelings</td></tr><tr><td>8</td><td>Education</td></tr><tr><td>9</td><td>Enjoyment and achievement</td></tr><tr><td>10</td><td>Health and well-being</td></tr><tr><td>11</td><td>Positive relationships</td></tr><tr><td>12</td><td>Protection of children</td></tr><tr><td>13</td><td>Leadership and management</td></tr><tr><td>14</td><td>Care planning</td></tr></table><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Read your home\'s statement of purpose and the Guide to the Children\'s Homes Regulations, and be able to say how your practice reflects them.</li><li>Know each child\'s care plan, risk assessment and health needs before you need them in a crisis.</li><li>Record children\'s views in their own words and show what changed as a result.</li><li>Treat education and health appointments as non-negotiable priorities.</li><li>Plan enjoyable, ordinary childhood experiences deliberately, for each individual child.</li><li>Use relationships, de-escalation and restorative approaches as your first tools for behaviour.</li><li>Report maintenance issues, safeguarding concerns and missing episodes promptly and follow them up.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t treat the standards as office paperwork separate from your shift.</li><li>Don\'t use blanket rules, group sanctions or punitive consequences that ignore individual needs and plans.</li><li>Don\'t dismiss complaints or grumbles; they are evidence of a home where children feel able to speak.</li><li>Don\'t accept a child being out of education as normal or unavoidable.</li><li>Don\'t let restraint become routine; it must be necessary, proportionate and always recorded and reviewed.</li><li>Don\'t support an admission or a move without honest thought about impact on every child in the home.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('cqc-single-assessment-framework', 'guides', 'What CQC Looks for Under the Single Assessment Framework', 'How CQC\'s single assessment framework works: the five key questions, quality statements, evidence categories and what they mean for care staff.', 'CQC now assesses services through its single assessment framework, built on the five key questions, a set of quality statements written as we statements, and defined evidence categories. This guide explains the structure and what frontline staff and managers should expect.', '["Health and Social Care Act 2008","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014","Care Quality Commission (Registration) Regulations 2009","Care Act 2014"]', '<p>The Care Quality Commission (CQC) regulates adult social care in England under the Health and Social Care Act 2008. Its single assessment framework, rolled out from late 2023, replaced the old key lines of enquiry (KLOEs) and the old model of judgement resting mainly on a site inspection every few years. Under the new framework, CQC gathers evidence on an ongoing basis, assesses against quality statements, and can update parts of its judgement without a full inspection. Site visits still happen, but they are one evidence-gathering tool among several. Details and current guidance are on cqc.org.uk.</p><h2>The five key questions</h2><p>The five key questions survive from the old framework and remain the backbone of ratings. For every service CQC asks whether it is:</p><ul><li><strong>Safe</strong>: are people protected from abuse and avoidable harm?</li><li><strong>Effective</strong>: does care achieve good outcomes and reflect evidence-based practice?</li><li><strong>Caring</strong>: do staff treat people with kindness, dignity, compassion and respect?</li><li><strong>Responsive</strong>: is care organised around individual needs and preferences?</li><li><strong>Well-led</strong>: do leadership, governance and culture support high-quality, person-centred care?</li></ul><p>Services are still rated outstanding, good, requires improvement or inadequate, both per key question and overall.</p><h2>Quality statements: the we statements</h2><p>Under each key question sits a set of quality statements, 34 in total across the framework, written as commitments from the provider\'s point of view, which is why they are called we statements. Examples include: we make sure there are enough qualified, skilled and experienced people to deliver safe care; we treat people as individuals; we have a proactive and positive culture of safety based on openness and honesty, in which concerns are listened to. Each quality statement replaces the old KLOEs and prompts, and links directly to the regulations underneath, chiefly the Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, which contain the fundamental standards such as person-centred care (Regulation 9), dignity and respect (Regulation 10), safe care and treatment (Regulation 12), safeguarding (Regulation 13), staffing (Regulation 18) and good governance (Regulation 17).</p><p>For a frontline team, the practical meaning is this: CQC is checking whether the we statements are actually true of your service. Every quality statement can be translated into a shift-level question. We involve people in decisions about their care becomes: can this resident describe how their care plan was written with them? We learn from safety events becomes: can staff describe a recent incident and what changed because of it?</p><h2>The six evidence categories</h2><p>For each quality statement, CQC collects evidence in defined categories:</p><ol><li><strong>People\'s experiences</strong> of health and care services: conversations with people using the service, families and advocates, surveys, complaints and feedback given directly to CQC.</li><li><strong>Feedback from staff and leaders</strong>: interviews and conversations on site, staff surveys, and information staff send to CQC directly, including whistleblowing.</li><li><strong>Feedback from partners</strong>: commissioners, local authorities, safeguarding teams, healthcare professionals who visit the service.</li><li><strong>Observation</strong>: what assessors see during visits, including interactions, mealtimes, the environment and how staff support people.</li><li><strong>Processes</strong>: policies, care plans, audits, rotas, training records, medication records, recruitment files and governance documents.</li><li><strong>Outcomes</strong>: measurable results of care, such as pressure care outcomes, falls data or hospital admissions. Not every evidence category is used for every quality statement or service type; CQC publishes which categories apply where.</li></ol><p>Notice how little of this is inspection-day performance. People\'s experiences, partner feedback and outcomes accumulate over months. A service cannot tidy its way to a rating the week before a visit, which is the point of the design.</p><h2>Scoring</h2><p>Evidence in each category is scored on a four-point scale, from 4 (evidence shows an exceptional standard) down to 1 (evidence shows significant shortfalls). Category scores combine into a score for each quality statement, quality statement scores build into a score for each key question, and those map onto the familiar ratings. The arithmetic matters less to frontline staff than the principle: judgements are now built from many small pieces of evidence, gathered over time, from multiple directions.</p><h2>What this means on shift</h2><ul><li><strong>Conversations count as evidence.</strong> When an assessor asks how you protect someone\'s dignity during personal care, or how you would report abuse, your answer feeds a scored evidence category. Specific, honest answers about real people beat policy recitation.</li><li><strong>Observation counts.</strong> How you knock on doors, talk over lunch, respond to distress and speak about people in the office is evidence under the caring and safe questions.</li><li><strong>Records count, continuously.</strong> Care plans, MAR charts, daily notes and incident records are process evidence. They need to be right every week, not just before a visit.</li><li><strong>Speaking up counts.</strong> The framework explicitly values a culture where concerns are raised and acted on. Staff can also give feedback to CQC directly at any time through its website.</li></ul><h2>What managers should be doing</h2><p>Registered managers should map their assurance activity to the quality statements rather than the old KLOEs: audits, surveys and governance reports organised by we statement make it straightforward to show evidence when CQC asks, including through provider information returns. Keep evidence of learning from incidents, complaints and safeguarding, because we learn, we improve is a theme running through the whole framework. And keep statutory notifications to CQC (under the 2009 registration regulations) accurate and prompt, since gaps there undermine the well-led picture fast.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Learn the five key questions and be able to connect your daily work to them.</li><li>Read the quality statements for adult social care and turn each into a question about your own service.</li><li>Give assessors specific, truthful examples about real people and real incidents.</li><li>Keep care plans, daily records and MAR charts accurate every day, because processes are a scored evidence category.</li><li>Treat feedback from people, families and visiting professionals as evidence you actively gather and act on.</li><li>Raise concerns internally, and know that staff can contact CQC directly at any time.</li><li>Record learning from incidents and complaints so improvement can be evidenced.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t assume assessment only happens during a site visit; evidence is collected continuously.</li><li>Don\'t coach staff in scripted answers; assessors triangulate what they hear against what they see and read.</li><li>Don\'t ignore the observation category: everyday interactions are inspected evidence.</li><li>Don\'t leave notifications, audits or action plans until an inspection is rumoured.</li><li>Don\'t treat complaints and incidents as embarrassments to bury; the framework rewards visible learning.</li><li>Don\'t rely on outdated KLOE-based toolkits; check current guidance on cqc.org.uk.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('de-escalation-low-arousal', 'guides', 'De-escalation and Low-Arousal Approaches', 'Practical de-escalation and low-arousal techniques for care settings: body language, environment, timing, what to say, and how to debrief afterwards.', 'De-escalation is a set of learnable skills, not a personality trait. This guide covers low-arousal principles, body language, the environment, what to say and not say during an incident, and why debriefing afterwards matters as much as the incident itself.', '["Children\'s Homes (England) Regulations 2015 (Regulation 20, restraint)","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014 (Regulation 12)","Mental Capacity Act 2005","Human Rights Act 1998"]', '<p>Every service that supports people who sometimes become distressed, whether a children\'s home under Ofsted or an adult service under CQC, has a legal and moral duty to prevent crisis where possible and to respond to it in the least restrictive way. Restraint is lawful only when necessary and proportionate, and in children\'s homes it is tightly limited by Regulation 20 of the Children\'s Homes (England) Regulations 2015. The Restraint Reduction Network standards, widely adopted across health and social care, make the direction of travel clear: services are expected to reduce restrictive practices year on year. The practical route to that is de-escalation, and behind good de-escalation sits the low-arousal approach.</p><h2>What low arousal means</h2><p>The low-arousal approach, developed by clinical psychologist Andrew McDonnell and colleagues, starts from a blunt observation: in a crisis, the person is already carrying more stress than they can manage, and most of what staff instinctively do adds stress rather than removes it. Demands, questions, crowding, eye contact, touch, raised voices and audiences all increase arousal. The low-arousal response is to strip demands and stimulation right down until the person can regulate again. You are not trying to win the moment; you are trying to lower the temperature.</p><p>A second principle matters just as much: your own arousal is contagious. If you are tense, loud and fast, you feed the crisis. If you are slow, quiet and genuinely calm, you offer the person a nervous system to borrow. Managing yourself is the first technique.</p><h2>Before the crisis: know the signs and the plan</h2><p>Most incidents have a build-up. Learn each person\'s individual signs of rising distress, such as pacing, going quiet, a particular phrase, seeking or avoiding people, and the triggers that commonly precede them, such as transitions, contact visits, noise, hunger or perceived unfairness. Every person who may become distressed should have an individual behaviour support or safety plan describing what helps and what makes things worse. Read it before you need it. Acting early, with a snack, a walk, a change of face or simply naming what you see, is the most effective de-escalation there is.</p><h2>During: body language and position</h2><ul><li><strong>Distance.</strong> Give more personal space than usual, at least a couple of arm\'s lengths. Crowding is a threat signal.</li><li><strong>Angle.</strong> Stand at a slight angle rather than square-on, which reads as confrontation. Keep your hands visible, open and low.</li><li><strong>Height.</strong> If it is safe, lower yourself: sit, lean, drop your shoulders. Towering over someone escalates.</li><li><strong>Eyes.</strong> Soften eye contact; do not stare someone down, and do not demand they look at you.</li><li><strong>Movement.</strong> Move slowly and predictably. Say what you are going to do before you do it.</li><li><strong>Voice.</strong> Slower, lower, quieter. Short sentences. Long pauses. Silence is a tool, not a failure.</li></ul><h2>During: what to say and what to avoid</h2><p>Say less than you think you need to. A distressed brain processes little language. Helpful lines are short, warm and low-demand: I\'m here. You\'re not in trouble. Take your time. I can see this is really hard. Offer simple, genuine choices where you can, such as would you rather be in your room or the garden, because choice returns a sense of control.</p><p>Avoid the classics that escalate: calm down (nobody has ever calmed down on request), threats and ultimatums, sarcasm, why questions, arguing back over insults, listing consequences mid-crisis, and dragging up earlier incidents. Do not take the bait of personal abuse; it is arousal talking. If a rule or refusal must stand, state it once, briefly and without triumph, then move back to empathy.</p><h2>During: the environment and the audience</h2><p>Think of the room as part of the intervention. Reduce noise, turn off the television, dim harsh lighting if you can. Remove the audience, because peers watching raise the stakes for everyone; it is usually easier to move other people away than the distressed person. Clear obvious hazards quietly. Know your exits and never let yourself be trapped in a corner, and avoid trapping the other person, because a blocked escape route turns distress into panic.</p><p>Consider a change of face. If you are the trigger, or the relationship is inflamed, handing over to a colleague is skilled practice, not defeat. Agree quiet signals in the team for swapping in and out.</p><h2>If de-escalation does not work</h2><p>Sometimes, despite everything, there is immediate risk of serious harm. Any physical intervention must be necessary, proportionate, for the shortest possible time, and carried out only by staff trained in an accredited approach; in children\'s homes it must never be used as punishment, and Regulation 20 requires a written record and the opportunity for the child to add their view. Restraint is always a sign that prevention has run out, and every use should prompt the question: what could we change so this is not needed next time?</p><h2>After: debrief, twice</h2><p>The incident is not over when the shouting stops. Two debriefs matter.</p><p><strong>With the person.</strong> Once they are genuinely calm, which may be hours later or the next day, reconnect gently. The goals are repair and learning, not blame: checking they are okay, hearing their account, acknowledging anything staff got wrong, and agreeing together what might help next time. For children, this supports the positive relationships standard; for adults, it is part of person-centred care under Regulation 9 of the 2014 regulated activities regulations.</p><p><strong>With the team.</strong> A staff debrief covers facts, feelings and learning: what happened, what the early signs were, what worked, what escalated things, and what changes to the plan, the environment or the rota follow. Staff involved in frightening incidents need support too; unprocessed incidents fuel burnout and defensive practice. Update the person\'s support plan with anything learned, and make sure recording is factual and complete, including antecedents, staff responses and any physical intervention.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Learn each person\'s triggers, early warning signs and support plan before a crisis, and act early.</li><li>Manage your own arousal first: breathe, slow down, drop your voice and shoulders.</li><li>Give space, stand at an angle, keep hands open and movements slow and announced.</li><li>Use few words, long pauses, empathy and simple genuine choices.</li><li>Reduce noise, remove the audience and keep escape routes open for everyone.</li><li>Swap staff when a change of face would lower the temperature.</li><li>Debrief with the person and the team after every significant incident, and update the plan.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t crowd, touch, stare down or stand square-on to a distressed person.</li><li>Don\'t say calm down, issue ultimatums, argue with insults or list consequences mid-crisis.</li><li>Don\'t pile in multiple staff all talking at once; one calm voice leads.</li><li>Don\'t corner the person or let yourself be cornered.</li><li>Don\'t use restraint unless there is immediate risk of serious harm, and never as punishment or for convenience.</li><li>Don\'t skip the debrief or leave records vague; every incident is data for prevention.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('medication-basics-6rs-mar-charts', 'guides', 'Medication Basics: The 6 Rs, MAR Charts and Common Errors', 'Medication administration basics for adult social care: the 6 Rs, completing MAR charts correctly, PRN protocols and how to handle errors.', 'Safe medication practice rests on a small number of disciplined habits: the 6 Rs, accurate MAR charts and honest error reporting. This guide covers each of them for adult social care staff, including PRN protocols and what to do when something goes wrong.', '["Health and Social Care Act 2008 (Regulated Activities) Regulations 2014 (Regulations 12 and 20)","Mental Capacity Act 2005","Misuse of Drugs Act 1971 and Misuse of Drugs Regulations 2001 (controlled drugs)","NICE guideline SC1: Managing medicines in care homes (2014)"]', '<p>Medication is one of the highest-risk routine activities in adult social care. Errors are common across the sector, most are preventable, and the defences against them are neither complicated nor expensive: trained staff, the 6 Rs, accurate MAR charts, clear PRN protocols and a culture that reports mistakes fast. The legal footing is Regulation 12 of the Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, which requires the safe management of medicines, and the detailed good practice reference is NICE guideline SC1, Managing medicines in care homes. Only staff trained and assessed as competent should administer medication, with competency reviewed regularly.</p><h2>The 6 Rs of administration</h2><p>Before any medicine passes your hand, check the 6 Rs, every time, without shortcuts:</p><ol><li><strong>Right person.</strong> Confirm identity positively, by face, photograph on the MAR and, where used, asking the person their name. Never rely on a room number or habit, especially with new residents or agency shifts.</li><li><strong>Right medicine.</strong> Check the label against the MAR chart: name, strength and form. Be alert to look-alike and sound-alike medicines and to changes after hospital discharge.</li><li><strong>Right dose.</strong> Check the dose on the MAR against the label, including units. If a dose seems unusual, stop and query it with a senior, the pharmacist or the prescriber before giving anything.</li><li><strong>Right time.</strong> Check the scheduled time, the minimum interval since the last dose, and timing rules such as before or with food, or time-critical medicines like those for Parkinson\'s disease, where lateness causes real harm.</li><li><strong>Right route.</strong> Oral, topical, inhaled, patch, eye drops, PEG: give by the route prescribed, and only if you are trained for that route.</li><li><strong>Right to refuse.</strong> An adult with capacity may decline medication, and their refusal must be respected, recorded with the correct MAR code and reported so the prescriber can review. Refusal is information, not defiance. If the person lacks capacity for this decision, a best-interests process under the Mental Capacity Act 2005 applies, and any covert administration needs a documented multidisciplinary plan involving the prescriber and pharmacist.</li></ol><p>Some services add further Rs, such as right documentation and right to a review; the habit of checking systematically matters more than the exact count.</p><h2>MAR charts: the golden rules</h2><p>The medication administration record (MAR) is the legal record of what was given, and often the first document an assessor, coroner or safeguarding enquiry reads. The rules are simple and unforgiving:</p><ul><li><strong>Sign at the time, not before, not later.</strong> Sign immediately after the person has taken the medicine. Signing in advance records something that has not happened; batch-signing at the end of a round invites omissions.</li><li><strong>Never leave gaps.</strong> An empty box is an unexplained mystery that reads as a missed dose. If a medicine was not given, enter the correct code for the reason, such as refused, nausea or vomiting, hospitalised, or medicine unavailable, using your service\'s code list, and record details in the notes.</li><li><strong>One task, one person, start to finish.</strong> Do not administer medicines someone else has prepared, and do not sign for anything you did not personally give. Never leave medicines out for later or for someone else to hand over.</li><li><strong>Handwritten entries need care.</strong> New or changed prescriptions transcribed by hand onto a MAR should be checked and countersigned by a second trained member of staff, with the prescriber\'s instruction as the source.</li><li><strong>Record variable doses and patches precisely.</strong> For a dose range, record the actual amount given. For patches, record the application site and rotate it.</li><li><strong>Controlled drugs</strong> have extra requirements under the Misuse of Drugs Act 1971 framework: storage in an approved cupboard, a controlled drugs register, and, in care homes with nursing and as good practice widely, witnessed administration and running balance checks.</li></ul><h2>PRN medicines: when required means a protocol, not a habit</h2><p>PRN (as required) medicines, such as pain relief, laxatives or anxiety medication, cause a disproportionate share of poor practice because they rely on judgement. Every PRN medicine should have an individual protocol stating: what it is for and the symptoms that indicate it; the dose, the minimum interval between doses and the maximum in 24 hours; how the person communicates the need, which matters especially where someone cannot verbally ask, so the protocol should describe the signs of pain or distress to look for; what to try first, such as repositioning or reassurance; and when to escalate to the GP. Record on the MAR the time given, the dose, the reason and, crucially, the outcome, whether it worked, checked after a suitable interval. Watch for drift: PRN given daily for weeks is a prescription review waiting to happen, and PRN sedation used for staff convenience rather than the person\'s distress is a restrictive practice and a safeguarding issue.</p><h2>Common errors and their causes</h2><p>The recurring errors in adult social care are: omitted doses, often masked by MAR gaps; wrong person, usually from interruptions or reliance on habit; wrong time, particularly time-critical medicines; double dosing after unclear handover or unsigned charts; transcription errors on handwritten MARs; missed changes after hospital discharge; and out-of-stock medicines not reordered in time. Behind most of them sit the same conditions: interruptions during the round, rushing, poor handover, and charts not completed in real time. Protect the round: many services use do-not-disturb tabards or quiet protocols, and every service can insist that the person administering is not pulled away mid-task.</p><h2>When an error happens</h2><p>Errors happen in good services; what distinguishes good services is what happens next. If you make or discover an error: first, check the person and make them safe; contact the GP, NHS 111, the pharmacist or 999 as the situation requires, and follow any advice given. Tell the senior on duty and the manager immediately. Record the facts on the MAR and in an incident report: what was given or missed, when, what advice was sought and what monitoring follows. Never falsify, backdate or quietly correct a chart; concealment turns a mistake into misconduct. The manager will consider onward duties: notification to CQC where the error caused or risked significant harm, safeguarding referral where neglect is in question, and the duty of candour under Regulation 20, which requires openness with the person and their family when notifiable harm occurs. A good employer treats honest error reporting as learning, reviews the systems behind the mistake, and reserves blame for concealment and recklessness; that is exactly the safety culture CQC\'s safe key question looks for.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Check all 6 Rs for every person, every medicine, every round, however routine it feels.</li><li>Sign the MAR immediately after administration, and use the correct code whenever a dose is not given.</li><li>Follow individual PRN protocols, record the reason and the outcome, and flag frequent PRN use for prescriber review.</li><li>Query anything unclear, unusual or illegible with a senior, the pharmacist or the prescriber before giving it.</li><li>Get handwritten MAR entries second-checked and countersigned.</li><li>Protect the medication round from interruptions and complete one person\'s medicines at a time.</li><li>Report every error and near miss immediately, and record it honestly.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t administer medicines you did not prepare, or sign for anything you did not personally give.</li><li>Don\'t pre-sign charts, leave gaps, or leave medicines out for later.</li><li>Don\'t override a capacitated refusal, or give medicines covertly without a documented best-interests plan.</li><li>Don\'t use PRN sedation for convenience or let regular PRN use continue without review.</li><li>Don\'t guess on doses, times or identities; stop and check.</li><li>Don\'t conceal, backdate or amend records after an error; report it and make the person safe first.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('mental-capacity-act-everyday-practice', 'guides', 'The Mental Capacity Act 2005 in Everyday Practice', 'The five principles of the Mental Capacity Act 2005 in everyday adult care, with worked examples covering meals, medication, money and relationships.', 'The Mental Capacity Act 2005 shapes hundreds of small decisions on every shift, not just the big formal ones. This guide walks through the five statutory principles and shows how they apply to everyday situations in adult care: meals, medication, money and relationships.', '["Mental Capacity Act 2005","Mental Capacity Act Code of Practice (2007)","Deprivation of Liberty Safeguards (Mental Health Act 2007 amendments)","Care Act 2014"]', '<p>The Mental Capacity Act 2005 (MCA) applies in England and Wales to everyone aged 16 and over. If you support adults who may have difficulty making some decisions, whether because of dementia, a learning disability, a brain injury or a mental health condition, the MCA is not background law. It is the framework for how you offer a cup of tea, hand over medication, help someone shop and respond when a person makes a choice you would not make yourself.</p><h2>The five principles</h2><p>Section 1 of the Act sets out five principles. Every decision you support or make on someone\'s behalf must follow them, in order.</p><ol><li><strong>A presumption of capacity.</strong> You must assume a person has capacity to make a decision unless it is established that they lack it. A diagnosis is never proof of incapacity.</li><li><strong>Support to make decisions.</strong> A person must not be treated as unable to decide until all practicable steps to help them have been taken without success. That means the right time of day, the right format, the right communication aids and enough time.</li><li><strong>The right to make unwise decisions.</strong> A person is not to be treated as lacking capacity merely because they make a decision others think is unwise. Capacity is about the process of deciding, not the outcome.</li><li><strong>Best interests.</strong> Any act done or decision made for a person who lacks capacity must be done in their best interests, following the checklist in section 4 of the Act.</li><li><strong>The least restrictive option.</strong> Before acting, consider whether the purpose can be achieved in a way that interferes less with the person\'s rights and freedom of action.</li></ol><h2>Capacity is decision-specific and time-specific</h2><p>Under sections 2 and 3 of the Act, a person lacks capacity for a particular decision at a particular time if they have an impairment or disturbance of the mind or brain, and because of that they cannot do one or more of the following: understand the relevant information, retain it long enough to decide, use or weigh it as part of the decision, or communicate their decision by any means.</p><p>This matters on shift because capacity fluctuates. Someone may be able to choose their lunch but not manage a tenancy agreement. Someone living with dementia may weigh a decision well at 10am and struggle at 6pm. You assess the decision in front of you, at the time it needs to be made, and you record what you saw, not just a conclusion.</p><h2>Worked example: meals</h2><p>Margaret, who has vascular dementia, refuses her pureed diet and asks for toast, despite a speech and language therapy recommendation because of swallowing risk.</p><p>Applying the principles: start by presuming she can make this choice. Support the decision, so explain the choking risk simply, at a calm moment, perhaps showing her the options. If she understands the risk, can hold onto it, weighs it against her strong preference for toast and tells you she still wants toast, she has capacity for this decision, and it is an unwise decision she is entitled to make. You would record the conversation, tell the manager, and look at ways to reduce risk she will accept, such as supervision while eating or a modified texture she finds acceptable. If she cannot understand or retain the risk information despite your best efforts, a best-interests decision is needed, and even then her wishes and feelings carry real weight in the section 4 checklist. The answer is rarely simply overriding her; it may be involving family, the SALT team and finding the least restrictive workable option.</p><h2>Worked example: medication</h2><p>David refuses his evening antipsychotic. Refusal is not, by itself, evidence he lacks capacity. Ask what is behind it: side effects, the taste, a belief he no longer needs it. Offer information in a form he can use. If he has capacity for this decision, you cannot force or hide medication; you record the refusal, monitor and escalate to the prescriber.</p><p>Covert medication, which means disguising medicine in food or drink, is only ever lawful for a person who lacks capacity for that decision, following a documented best-interests process involving the prescriber, pharmacist and those close to the person, with a written plan that is reviewed regularly. Slipping medication into tea because it is quicker is unlawful and a safeguarding matter.</p><h2>Worked example: finances</h2><p>Joan wants to give her nephew two hundred pounds from her personal allowance. Staff feel uneasy because he visits rarely and only asks for money. The unwise-decision principle applies: if Joan understands what she has, what she is giving, and the effect on her, it is her money. Discomfort is not a legal basis to stop her. But financial abuse is a genuine safeguarding category under the Care Act 2014, so if there are signs of pressure, coercion or a pattern of exploitation, raise a safeguarding concern; capacity to make a decision does not remove the duty to protect people from coercion. Check also whether anyone holds a registered Lasting Power of Attorney for property and affairs, or whether the Court of Protection has appointed a deputy, because that changes who can lawfully make which decisions.</p><h2>Worked example: relationships</h2><p>Two residents begin a relationship and staff worry about consent. Capacity to consent to sexual relations is decision-specific and the threshold of information is not high, but a person must be able to understand and weigh the relevant information, including the other person\'s ability to consent. If both have capacity, they have the same right to a private life as anyone else, under Article 8 of the European Convention on Human Rights, and the service should support privacy and dignity. If there is genuine doubt about either person\'s capacity, do not improvise: record concerns factually, involve the manager, and seek advice, because a person who lacks capacity cannot consent and others cannot consent on their behalf.</p><h2>Best interests and restriction</h2><p>When a best-interests decision is needed, section 4 requires you to consider the person\'s past and present wishes, feelings, beliefs and values, consult those close to them and anyone with legal authority, involve the person as far as possible, and not make assumptions based on age, appearance or condition. Choose the least restrictive option that meets the need. If the arrangements amount to a deprivation of liberty, meaning the person is under continuous supervision and control and is not free to leave, and they lack capacity to consent to those arrangements, an authorisation is needed under the Deprivation of Liberty Safeguards. Restriction without authorisation is not a paperwork problem; it is a human rights problem.</p><h2>Recording</h2><p>Good MCA practice lives or dies in the records. Write down the decision in question, the support you offered, what the person said and did, your assessment against the four functional abilities, who you consulted and why the chosen option was the least restrictive. A record that says only that a person lacks capacity will not stand up to scrutiny from CQC, a safeguarding enquiry or the Court of Protection.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Presume capacity for every decision, every time, whatever the diagnosis.</li><li>Assess capacity for the specific decision at the specific time it arises.</li><li>Take all practicable steps to support the decision before concluding anyone lacks capacity: timing, communication aids, familiar people, plain language.</li><li>Respect unwise decisions made with capacity, and manage risk around them.</li><li>Use the section 4 best-interests checklist and consult family, advocates and attorneys or deputies.</li><li>Record what you observed, what you tried and how you reached your conclusion.</li><li>Raise a safeguarding concern where you suspect coercion or abuse, even if the person appears to have capacity.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t treat a diagnosis, age or appearance as evidence of incapacity.</li><li>Don\'t label a decision as lacking capacity just because it is risky or inconvenient.</li><li>Don\'t give medication covertly without a documented best-interests process involving the prescriber.</li><li>Don\'t apply one capacity assessment to every decision or assume it lasts forever.</li><li>Don\'t restrict someone\'s freedom without considering less restrictive options and, where needed, lawful authorisation.</li><li>Don\'t record bare conclusions without the evidence and reasoning behind them.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('professional-boundaries-residential-care', 'guides', 'Safer Working Practice: Professional Boundaries in Residential Care', 'Professional boundaries for residential care staff: gifts, touch, social media, self-disclosure, favouritism and how allegations are managed.', 'Professional boundaries protect the people you care for, and they protect you. This guide covers the everyday boundary areas in residential work, including gifts, touch, social media, self-disclosure and favouritism, and explains how allegations against staff are managed.', '["Children\'s Homes (England) Regulations 2015","Working Together to Safeguard Children (statutory guidance)","Sexual Offences Act 2003 (abuse of position of trust, sections 16 to 24)","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014 (Regulation 13)"]', '<p>Residential care is intimate work. You share meals, bad days, birthdays and bereavements with the people you support. Warmth is not just permitted, it is the job. Professional boundaries are what make that warmth safe: they keep the relationship organised around the other person\'s needs rather than the worker\'s, they protect children and adults at risk from exploitation, and they protect staff from misunderstandings and allegations. The Safer Recruitment Consortium\'s Guidance for Safer Working Practice, widely used across children\'s settings, is the reference point for much of what follows, alongside your own service\'s code of conduct, which you should read and follow.</p><p>One legal point frames everything in children\'s services: under sections 16 to 24 of the Sexual Offences Act 2003, sexual activity by a person in a position of trust, which includes residential care staff, with a young person in their care is a criminal offence even where the young person is 16 or 17 and even where they describe it as consensual. There are no grey areas here.</p><h2>The core test</h2><p>Almost every boundary question yields to the same test: whose need is being met? Care relationships exist for the benefit of the person being cared for. If an interaction, gift, disclosure or contact primarily meets the worker\'s emotional needs, it is a boundary problem, however innocent it feels. A useful companion test: would I be comfortable if my manager, the person\'s social worker and an inspector could see this? If the honest answer involves secrecy, stop.</p><h2>Gifts and money</h2><p>Giving occasional small gifts to the people you support is normal in residential settings, but it should be visible, recorded where your policy requires, and even-handed; a worker who regularly buys presents for one child is creating favouritism and grooming-pattern behaviour whether or not anything sinister is intended. Receiving gifts needs equal care: small tokens may be acceptable and should be declared under your gifts policy, but money, valuable items or repeated gifts should be declined kindly and reported. Never lend money to or borrow money from someone you support or their family, never sell things to them or buy from them, and never become involved in their wills or finances beyond your role. In adult services, financial abuse is a safeguarding category under the Care Act 2014, and blurred money boundaries are how it starts.</p><h2>Touch and physical contact</h2><p>Touch matters to human beings, and a blanket no-touch rule is neither realistic nor kind, especially with children who need comfort or adults receiving personal care. The standard is that touch should be in response to the person\'s need, appropriate to age, culture, history and setting, generally in view of others, and something you would be comfortable recording and explaining. Trauma histories change what touch means; know each person\'s plan, and let the person lead. Personal care must follow the care plan and respect dignity. What is never acceptable: touch as punishment, horseplay that a young person cannot easily opt out of, tickling, kissing, or any contact with a sexual element. If a child initiates a hug, respond warmly and appropriately; side-on hugs in communal areas are the safer norm. Record any physical contact that felt significant or could be misread.</p><h2>Social media and phones</h2><p>The rules here are unambiguous in most services. Do not send friend requests to, or accept them from, people you support or their families on personal accounts, during placement or after it without explicit management agreement. Do not follow, message or contact them from personal accounts, do not share your personal number, and do not photograph them on your personal phone. Never post anything about work, the people you support or colleagues that could identify them, even vaguely and even in closed groups. Set your own accounts to private and assume the people you support will look for you, because they will. Any contact a person attempts through social media should be reported and recorded, not hidden, and not handled privately.</p><h2>Self-disclosure</h2><p>Sharing something of yourself can build relationships, and residential workers are not blank screens. The test is purpose and proportion: brief, considered disclosure that serves the other person, such as mentioning that you also found exams stressful, differs from using shift time to discuss your relationship problems, finances, or detailed personal history. Never share your address, your own trauma in unprocessed detail, or information that invites the person to take care of you. Never ask a person to keep something about you secret; secrecy between a worker and a person in their care is the single loudest warning sign in safer working practice.</p><h2>Favouritism and special relationships</h2><p>Connection is uneven; liking some people more than others is human. Acting on it is the boundary issue. Warning signs in yourself or colleagues include: spending disproportionate time with one person, swapping shifts to be with them, gifts or treats for one person, sharing secrets, allowing rule exceptions for them, contact outside work, and feeling that you are the only one who understands them. That last feeling deserves particular respect as a danger sign: it is how boundary drift feels from the inside, and it is also how grooming looks from the outside. The remedy is daylight: talk to your supervisor about the relationship, share the keywork, and let the team rebalance it.</p><h2>When boundaries slip: yours and others\'</h2><p>Boundary drift is gradual, which is why supervision exists. Raise your own wobbles early; a worker who says I think I am getting over-involved is demonstrating professionalism, not failure. If you see a colleague crossing boundaries, you must report it, through your manager, safeguarding lead or whistleblowing route; loyalty to colleagues never outranks safety, and low-level concerns reported early are how organisations stop harm before it happens.</p><h2>Allegations management</h2><p>If an allegation is made against you, or you are reported for a boundary concern, a defined process follows. In children\'s services, allegations that a person working with children has behaved in a way that has harmed or may have harmed a child, possibly committed a criminal offence, or behaved in a way indicating they may pose a risk, must be referred to the local authority designated officer (LADO) under the Working Together to Safeguard Children framework, and children\'s homes must also notify Ofsted of significant events. In adult services, safeguarding procedures under the Care Act 2014 and notification duties to CQC apply. You may be moved to other duties or suspended as a neutral act while enquiries take place. Cooperate, be honest, and use your union or a representative for support. The strongest protection against unfounded allegations is the practice described above: visible, recorded, even-handed work with nothing done in secret.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Apply the two tests constantly: whose need is this meeting, and would I be comfortable if my manager could see it?</li><li>Keep interactions visible: communal spaces, open doors where plans allow, and records of anything significant.</li><li>Declare gifts in both directions and follow your service\'s gifts and gratuities policy.</li><li>Follow each person\'s care plan on touch and personal care, and let their needs and history lead.</li><li>Lock down your personal social media and report any contact attempts from people you support.</li><li>Use supervision to talk honestly about attachments, favourites and boundary wobbles.</li><li>Report colleagues\' boundary concerns early, however uncomfortable that feels.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t give out your personal number, address or social media, or contact people you support from personal accounts.</li><li>Don\'t ask anyone in your care to keep a secret with you, ever.</li><li>Don\'t single one person out for gifts, treats, exceptions or your time.</li><li>Don\'t lend, borrow, buy, sell or get entangled in the finances of people you support.</li><li>Don\'t use the people you care for as your emotional support or audience for your personal life.</li><li>Don\'t handle boundary problems, yours or a colleague\'s, privately; daylight and reporting are the only safe responses.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('trauma-informed-care-and-pace', 'guides', 'Trauma-Informed Care and PACE in Everyday Interactions', 'What trauma-informed care and Dan Hughes\'s PACE approach (Playfulness, Acceptance, Curiosity, Empathy) look like in real interactions with children.', 'Trauma-informed care means understanding behaviour as communication shaped by a child\'s earlier experiences, and responding in ways that build safety rather than shame. This guide explains the thinking behind it and shows how Dan Hughes\'s PACE approach works in ordinary moments on shift.', '["Children Act 1989","Children\'s Homes (England) Regulations 2015 (Regulations 6, 11 and 12)","Working Together to Safeguard Children (statutory guidance)","Equality Act 2010"]', '<p>Most children living in residential care have experienced abuse, neglect, loss or repeated moves. Trauma-informed care starts from a simple shift in question: not what is wrong with this child, but what has happened to this child, and what are they telling us through their behaviour. It is not a therapy you deliver in sessions. It is the way the whole home relates to children, every hour of the day, and it sits squarely within the quality and purpose of care and positive relationships standards in the Children\'s Homes (England) Regulations 2015.</p><h2>What trauma does</h2><p>Developmental trauma, meaning frightening or neglectful experiences within early relationships, shapes how a child\'s brain and body learn to survive. A child who has needed to stay hyper-alert to danger may read neutral faces as hostile, hear a raised voice as a threat, and move from calm to crisis in seconds. A child whose needs were ignored may have learned that adults cannot be trusted, that asking for help is dangerous, or that being controlling is the only way to be safe. Shame is often close to the surface: many traumatised children believe, deep down, that they are bad.</p><p>This is why consequences alone rarely change behaviour driven by trauma. A child in survival mode is not weighing sanctions; their thinking brain is offline. What changes things over time is repeated experience of adults who stay regulated, stay connected and stay kind, especially when the child is at their worst. Widely used trauma-informed principles include safety, trustworthiness, choice, collaboration and empowerment; in a children\'s home these are lived through routines, honesty, predictability and repair after ruptures.</p><h2>What PACE is</h2><p>PACE was developed by the American psychologist Dan Hughes as part of dyadic developmental psychotherapy, originally for parents of children who have experienced trauma and attachment disruption. It describes an attitude, a way of being with a child, built from four elements: Playfulness, Acceptance, Curiosity and Empathy. It is not a script or a technique to deploy when things go wrong; it is a stance you hold all the time, so that when things do go wrong, the relationship can carry the weight.</p><h3>Playfulness</h3><p>Playfulness is light, warm and unconditional. It says: I enjoy you, you are likeable, being with you is a pleasure. It is shared jokes, silly moments over breakfast, playful commentary during a car journey. For a child soaked in shame, playfulness delivered without an agenda is powerful evidence against their belief that they are unlovable. What it looks like on shift: joining in with a child\'s game without being asked, gentle humour that laughs with a child and never at them, and keeping lightness in the home even on hard days. What it is not: sarcasm, teasing about sensitive things, or using humour to dodge a child\'s distress.</p><h3>Acceptance</h3><p>Acceptance means accepting the child\'s inner experience, their feelings, wishes and view of the world, without needing to correct it first. You can accept a feeling while still holding a boundary on behaviour. A worked example: a child screams that you don\'t care about them because you have said no to a late-night trip out. An accepting response is: you\'re furious with me right now, and it feels like I don\'t care. I get why it feels that way. The answer about tonight is still no. Notice what is missing: no lecture, no of course I care followed by a list of evidence, no demand that the child be reasonable before they are heard.</p><h3>Curiosity</h3><p>Curiosity is wondering, without judgement, about what is going on underneath behaviour. It sounds like: I wonder if today felt hard because contact was cancelled. I noticed you went quiet when we talked about the school meeting; I might be wrong, but I wondered whether that felt scary. Curiosity is offered tentatively, as a guess the child is free to reject, and it works best well after the storm, not in the middle of it. Interrogation is the opposite of curiosity: why did you do that demands a justification the child usually does not have.</p><h3>Empathy</h3><p>Empathy is feeling with the child and letting them know it: that sounds really lonely; I can see how much that hurt. Empathy comes before problem-solving, and sometimes instead of it. Many traumatised children have never had an adult sit alongside their distress without minimising it, fixing it or punishing it. Doing exactly that, repeatedly, is the intervention.</p><h2>A real interaction, two ways</h2><p>A fifteen-year-old comes in an hour past curfew, smelling of smoke, and kicks the door when challenged.</p><p>Without PACE: You know the rules. That\'s your phone gone for two days. Kick that door again and I\'m calling the police. The child escalates or storms off; shame hardens; the home learns nothing about the missing hour.</p><p>With PACE: the adult stays low and calm. I\'m really glad you\'re back; I was worried about you. You seem wound up. Come and have some toast. Later, once the child is regulated: I wondered if something happened tonight, you seemed upset when you came in. The curfew still matters and is talked about the next day, along with any consequence, framed as keeping you safe rather than making you pay. The difference is not softness; it is sequencing. Connection first, correction after, and correction that protects the relationship.</p><h2>PACE and boundaries</h2><p>A common misreading is that PACE means no boundaries. In fact traumatised children need firm, predictable boundaries more than most, because predictability is safety. PACE changes how boundaries are held, not whether they exist: calmly, consistently, without contempt, and with repair afterwards. If you lose your temper, the trauma-informed move is to repair, honestly and soon: I got that wrong earlier, I raised my voice and I\'m sorry. Repair teaches children that relationships survive rupture, which may be the single most important lesson a home can offer.</p><h2>Looking after the adults</h2><p>You cannot lend a child regulation you do not have. Trauma-informed homes take staff supervision, reflective practice and debriefs seriously, and treat a colleague saying I\'m not the right person for this situation right now as professionalism, not weakness. Secondary trauma is real; use supervision to process it.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Ask yourself what the behaviour is communicating before deciding how to respond.</li><li>Connect before you correct: regulate, relate, then reason.</li><li>Name and accept feelings even when you are holding a firm boundary on behaviour.</li><li>Use tentative, judgement-free curiosity once the child is calm.</li><li>Repair quickly and honestly after ruptures, including your own mistakes.</li><li>Keep routines, plans and promises predictable; tell children in advance about changes.</li><li>Use supervision and debriefs to stay regulated and reflective yourself.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t take trauma-driven behaviour personally or respond with sarcasm and contempt.</li><li>Don\'t demand explanations mid-crisis or ask why questions a dysregulated child cannot answer.</li><li>Don\'t confuse acceptance of feelings with acceptance of unsafe behaviour.</li><li>Don\'t pile on shame with lectures, public tellings-off or consequences designed to hurt.</li><li>Don\'t use playfulness to mock, tease or deflect a child\'s distress.</li><li>Don\'t treat PACE as a crisis technique; it is a constant stance, and children spot inconsistency instantly.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('what-ofsted-inspectors-ask-frontline-staff', 'guides', 'What Ofsted Inspectors Actually Ask Frontline Staff', 'Realistic questions Ofsted inspectors ask residential childcare staff during inspection, and principles for answering honestly, confidently and well.', 'Ofsted inspectors routinely speak to frontline staff during children\'s home inspections, and those conversations carry real weight. This guide sets out the questions staff are most often asked, what inspectors are listening for, and how to answer honestly without rehearsed scripts.', '["Children\'s Homes (England) Regulations 2015","Care Standards Act 2000","Social care common inspection framework (SCCIF) for children\'s homes","Working Together to Safeguard Children (statutory guidance)"]', '<p>Under the social care common inspection framework (SCCIF), Ofsted inspectors spend most of an inspection gathering first-hand evidence: talking to children, observing daily life, reading records, and talking to staff at every level. If you work in a children\'s home, an inspector will at some point sit down with you, often informally, in the kitchen or during an activity, and ask questions. This is not a trap and it is not a memory test. Inspectors are trying to find out whether what the paperwork says is what actually happens, and whether staff know the children well enough to keep them safe and help them progress.</p><h2>What inspectors are really assessing</h2><p>SCCIF judgements centre on the experiences and progress of children, how well they are helped and protected, and the effectiveness of leaders and managers. When an inspector talks to you, they are triangulating: does what this staff member says match the care plans, the incident records, what children told me, and what I have seen on shift? Consistency between those sources is the strongest evidence a home can offer. Inconsistency, such as staff who cannot describe a child\'s risks, or who describe a sanctions culture the paperwork hides, is what sinks judgements.</p><h2>Questions you can realistically expect</h2><h3>About the children</h3><ul><li>Tell me about the children living here. What are they each like?</li><li>What progress has this child made since they arrived? How do you know?</li><li>What are this child\'s main risks, and what is in place to manage them?</li><li>What does this child\'s care plan say you are working on with them?</li><li>How do you support this child\'s education and health appointments?</li></ul><h3>About safeguarding</h3><ul><li>What would you do if a child told you a member of staff had hurt them?</li><li>What is your procedure when a child goes missing? What happens when they come back?</li><li>What do you know about criminal and sexual exploitation risks for these children?</li><li>Who is your designated safeguarding lead, and how do you contact the local authority designated officer (LADO)?</li><li>Have you ever raised a concern? What happened?</li></ul><h3>About whistleblowing and culture</h3><ul><li>What would you do if you had concerns about your manager?</li><li>Do you know how to contact Ofsted directly?</li><li>Would you feel safe raising concerns here? Why?</li></ul><h3>About you and the home</h3><ul><li>How long have you worked here? What was your induction like?</li><li>When was your last supervision? Is it useful?</li><li>What training have you done recently, and how has it changed your practice?</li><li>How are physical restraint and consequences used here? Talk me through the last incident you were involved in.</li><li>What is the home good at, and what could be better?</li></ul><h2>Principles for answering well</h2><h3>Be honest, including about problems</h3><p>Inspectors interview a lot of people and detect rehearsed answers quickly. A home where every staff member says everything is fantastic reads as coached, not outstanding. It is entirely acceptable, and often impressive, to say: we struggled with that placement, and here is what we changed. Honesty about weaknesses, paired with evidence that the home learns, is a hallmark of good leadership culture. Never guess or bluff; the strongest professional answer to a question you cannot answer is: I don\'t know, but I know exactly where I\'d find out, followed by where.</p><h3>Talk about children, not paperwork</h3><p>Answer with real children (using appropriate confidentiality) and real examples. Compare: we do keywork sessions weekly, with: I do keywork with A on Tuesdays; this month we\'ve been working on travel training because she wants to get to college independently, and last week she did the bus route with me shadowing. The second answer evidences care planning, education support, progress and relationship in two sentences. Specific beats general every time.</p><h3>Know your safeguarding answers cold</h3><p>Safeguarding is the one area where hesitation is costly. Every member of staff, including new and agency staff, should be able to state without notes: how to respond to a disclosure (listen, don\'t promise secrecy, don\'t ask leading questions, record in the child\'s words, report immediately); what the missing-from-home procedure is for each child; how to report an allegation against a colleague or manager, including going to the LADO and Ofsted directly if needed; and the home\'s whistleblowing route. If you cannot answer these today, that is this week\'s priority, not inspection week\'s.</p><h3>Show your working on restraint and consequences</h3><p>If asked about an incident, describe the build-up, what de-escalation you tried, why any physical intervention was necessary and proportionate, how the child was debriefed, and what changed afterwards. Inspectors are not looking for incident-free homes; they are looking for homes that respond lawfully, reflect and reduce.</p><h3>It is fine to be nervous</h3><p>Inspectors expect nerves and generally work hard to put staff at ease. Take your time, ask for a question to be repeated, and do not fill silence with speculation. You are allowed to say that you would like to check a record rather than answer from memory.</p><h2>What managers should do beforehand</h2><p>Registered managers should make inspection conversations unremarkable by making their content everyday practice: children discussed by name in every handover and team meeting, supervision that actually explores practice, safeguarding scenarios rehearsed in team meetings, and staff routinely asked the what would you do if questions long before an inspector does. Briefing staff to give particular answers is counterproductive and transparent; briefing staff on what inspection involves, so nobody is ambushed by the format, is simply good support.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Answer with specific, real examples about individual children and their progress.</li><li>Know your safeguarding, missing and allegations procedures without needing notes.</li><li>Be honest about difficulties and describe what the home learned and changed.</li><li>Say I don\'t know when you don\'t, and say where you would find the answer.</li><li>Describe de-escalation and reflection when talking about incidents, not just the incident itself.</li><li>Know how to contact the LADO and Ofsted directly, and say you would use those routes if needed.</li><li>Take your time; ask for questions to be repeated.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t recite rehearsed lines or claim everything is perfect.</li><li>Don\'t guess, bluff or speculate to fill silence.</li><li>Don\'t talk in paperwork abstractions when a real example is available.</li><li>Don\'t minimise incidents or describe consequences and restraint casually.</li><li>Don\'t criticise children or share information beyond what the question needs.</li><li>Don\'t treat the conversation as an interrogation; inspectors are cross-checking that good practice is real, and if it is, ordinary honesty shows it.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('whistleblowing-in-care', 'guides', 'Whistleblowing in Care: Your Rights and How to Raise Concerns', 'Whistleblowing protections for care workers under PIDA 1998 and ERA 1996, raising concerns internally, going to CQC or Ofsted, and the limits of NDAs.', 'Care workers who speak up about wrongdoing are protected by law, and knowing how the protection works makes it easier to use. This guide explains protected disclosures under the Public Interest Disclosure Act 1998, how to raise concerns internally, when to go to CQC or Ofsted, and why confidentiality clauses cannot silence you.', '["Public Interest Disclosure Act 1998","Employment Rights Act 1996 (Part IVA, sections 43A to 43L)","Prescribed Persons Order (Public Interest Disclosure (Prescribed Persons) Order 2014)","Care Act 2014"]', '<p>Care settings depend on staff who speak up. Almost every serious care scandal in recent memory was known about by frontline workers long before it became public. The law recognises this: the Public Interest Disclosure Act 1998 (PIDA) inserted Part IVA (sections 43A to 43L) into the Employment Rights Act 1996, protecting workers who blow the whistle from dismissal and detriment. Understanding how that protection works, before you ever need it, is part of being a safe practitioner.</p><h2>What counts as a protected disclosure</h2><p>You are protected when you make a qualifying disclosure in the right way. A qualifying disclosure is a disclosure of information which, in your reasonable belief, is made in the public interest and tends to show one or more of the following (section 43B):</p><ul><li>a criminal offence has been, is being or is likely to be committed;</li><li>a person has failed, is failing or is likely to fail to comply with a legal obligation;</li><li>a miscarriage of justice has occurred or is likely to;</li><li>the health or safety of any individual has been, is being or is likely to be endangered;</li><li>the environment has been, is being or is likely to be damaged;</li><li>information about any of the above has been or is likely to be deliberately concealed.</li></ul><p>In care, the health and safety and legal obligation categories cover most situations: abuse or neglect of residents or children, dangerous staffing levels, falsified records, medication mishandling, unsafe restraint, or a manager covering up incidents. Two points matter. First, you need a reasonable belief, not proof; a concern raised honestly and reasonably is protected even if it later turns out to be mistaken. Second, since 2013 the disclosure must be in the public interest, which concerns about the safety of people in care almost always are; a purely personal employment grievance is not whistleblowing and belongs in the grievance procedure instead.</p><p>The definition of worker for whistleblowing is wide: employees, agency workers and many contractors are covered. Protection means that dismissal for making a protected disclosure is automatically unfair (with no minimum service requirement), and that you must not be subjected to any detriment, such as demotion, harassment, reduced hours or being frozen out, because you spoke up. Compensation for whistleblowing dismissal is uncapped.</p><h2>Step one: raise it internally</h2><p>Disclosure to your employer (section 43C) is the most straightforwardly protected route, and usually the fastest way to get a problem fixed. Every registered service should have a whistleblowing policy naming who to contact, typically your manager, or a senior manager or nominated officer where the concern involves your manager. Raise the concern factually: what you saw or heard, when, who was involved, and any records that support it. Put it in writing or follow up a conversation in writing, keep a dated copy, and keep notes of any response. Safeguarding concerns about an individual at risk should also go through safeguarding procedures immediately, to the local authority under the Care Act 2014 for adults, or children\'s social care and the LADO where a child is at risk or an adult in a position of trust is implicated; safeguarding referral and whistleblowing are parallel duties, not alternatives.</p><h2>Step two: prescribed persons, including CQC and Ofsted</h2><p>If raising it internally fails, feels unsafe, or the wrongdoing involves those you would report to, the law protects disclosure to a prescribed person (section 43F). The Public Interest Disclosure (Prescribed Persons) Order 2014 lists them, and for care the key ones are the Care Quality Commission for adult social care services and Ofsted for children\'s homes and other children\'s services; the full list is on gov.uk. Disclosure to a prescribed person is protected where you reasonably believe the matter falls within that regulator\'s remit and that the information and any allegation in it are substantially true. You do not have to raise a concern internally first before going to CQC or Ofsted, although it is often sensible where it is safe to do so. Both regulators take whistleblowing contacts from care staff routinely, treat them as important intelligence, and will not reveal your identity without your consent except where required by law. Local authority commissioners and, for crimes, the police are also legitimate routes.</p><p>Disclosures made in the course of obtaining legal advice (section 43D) are also protected, so speaking to a solicitor, your trade union or an advice line such as the whistleblowing charity Protect is always safe ground. Wider disclosures, for example to the media (section 43G and 43H), are protected only in tighter circumstances, generally involving exceptionally serious failures or reasonable fear of cover-up or reprisal, and higher tests apply; take advice before going down that road.</p><h2>NDAs and confidentiality clauses cannot gag you</h2><p>Section 43J of the Employment Rights Act 1996 makes any provision in an agreement void in so far as it purports to prevent a worker from making a protected disclosure. That includes confidentiality clauses in employment contracts and non-disclosure or confidentiality terms in settlement agreements signed when leaving a job. An employer can lawfully require you to keep genuinely confidential information confidential, but no contract can stop you reporting wrongdoing to CQC, Ofsted, the police or another prescribed person, and a clause claiming otherwise is unenforceable to that extent. If you are asked to sign a settlement agreement, the solicitor advising you should confirm this; if a manager tells you that you signed something so you cannot speak to the regulator, they are wrong in law.</p><h2>Practical realities</h2><p>Whistleblowing can still be hard, and pretending otherwise helps no one. Reduce the risks by acting early, before frustration turns concerns into conflict; sticking to facts and records rather than accusations about motives; using the policy routes so your disclosure is clearly within the protected framework; keeping your own dated notes of what you raised, to whom and what happened; and getting advice from your union or Protect if you meet resistance. If you suffer reprisals, note each incident with dates and take advice promptly, because employment tribunal claims have short time limits, normally three months less one day from the act complained of. Managers reading this have the mirror-image duty: a service where staff raise concerns easily and see them acted on is safer, and both CQC\'s well-led question and Ofsted\'s leadership and management standard look for exactly that culture of openness.</p><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Raise concerns early, factually and through your whistleblowing policy, and keep dated copies.</li><li>Report safeguarding concerns immediately through safeguarding procedures as well; the two duties run in parallel.</li><li>Go to CQC or Ofsted as prescribed persons if internal routes fail or are unsafe; you do not need permission.</li><li>Take advice from your trade union, a solicitor or the charity Protect; those conversations are protected.</li><li>Keep a written record of what you disclosed, to whom, when and what response you received.</li><li>Managers: treat concerns as free safety intelligence, protect the person raising them, and feed back what changed.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t wait for proof; a reasonable, honest belief is enough to raise a concern.</li><li>Don\'t dress a personal grievance up as whistleblowing, or a safeguarding concern down as a grumble.</li><li>Don\'t be silenced by a confidentiality clause or NDA; section 43J makes gagging clauses void for protected disclosures.</li><li>Don\'t go to the media before taking advice; wider disclosures carry stricter legal tests.</li><li>Don\'t victimise, ostracise or quietly punish a colleague who spoke up; detriment is unlawful and uncapped compensation applies to dismissal.</li><li>Don\'t sit on evidence of reprisals; tribunal time limits are short.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('writing-daily-logs-that-stand-up-to-scrutiny', 'guides', 'Writing Daily Logs and Records That Stand Up to Scrutiny', 'How to write daily logs in care that stand up to inspection, court and subject access: fact versus opinion, third-party information and good habits.', 'Daily logs are legal documents that may one day be read by inspectors, courts, safeguarding enquiries and the person they are about. This guide covers separating fact from opinion, handling third-party information, subject access awareness and the habits that make records defensible.', '["Data Protection Act 2018","UK General Data Protection Regulation (UK GDPR)","Children\'s Homes (England) Regulations 2015 (Regulation 36 and Schedule 3)","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014 (Regulation 17)"]', '<p>Every daily log, incident report and keywork note you write is a legal record. It may be read by an Ofsted or CQC inspector next month, by a safeguarding enquiry next year, by a family court, by a coroner, or, years from now, by the person it describes, reading their own file to understand their childhood or their care. Good recording is not bureaucracy. It is part of the care itself, and in regulated services it is a legal duty: Regulation 36 and Schedule 3 of the Children\'s Homes (England) Regulations 2015 for children\'s homes, and Regulation 17 (good governance) of the 2014 regulated activities regulations for CQC-registered services.</p><h2>Write for the future reader</h2><p>The most useful habit is to picture two readers before you type a word. The first is a professional who was not there, reading in a crisis two years from now, who needs to know exactly what happened. The second is the person themselves, exercising their legal right to read their records. If your entry would embarrass you in front of either, rewrite it. Records written with warmth and precision protect everyone; records written in frustration, jargon or shorthand protect no one, least of all you.</p><h2>Fact versus opinion</h2><p>The single most common weakness in care records is opinion dressed as fact. Compare:</p><ul><li><strong>Opinion as fact:</strong> Jordan was attention-seeking and aggressive all evening.</li><li><strong>Factual:</strong> Between 7pm and 9pm Jordan came into the office four times asking staff to sit with him. At around 8.45pm, when asked to wait until handover finished, he shouted, you never have time for me, and kicked the office door once, leaving a scuff mark. No one was hurt.</li></ul><p>The second version tells a future reader what actually happened, lets patterns emerge, and, read by Jordan later, describes his behaviour without labelling his character. Words like aggressive, manipulative, attention-seeking, kicked off, rude and challenging are conclusions, not observations. Record what you saw and heard: actions, direct quotes where significant, times, places, who was present, and what staff did in response.</p><p>Professional judgement still belongs in records, but flag it as judgement and give your grounds: Jordan seemed flat and withdrawn this evening; he declined dinner and his favourite TV programme, which is unusual for him. That is opinion done properly, because it is labelled, attributed and evidenced.</p><h2>Complete means including staff actions and follow-up</h2><p>A record of an incident without the staff response is half a record. Always capture what staff did, what worked, what was said to the person afterwards, who was informed, such as the manager, social worker or family where appropriate, and what follow-up is planned. Inspectors and courts are as interested in the response as the event. If you gave first aid, offered emotional support, made a safeguarding referral or updated a risk assessment, say so, with times.</p><h2>Timeliness, accuracy and corrections</h2><p>Write up as soon as practicable, ideally the same shift, and record the time of the event as well as the time of writing. Memory degrades fast and late records invite challenge. Never alter a record after the fact to make it look better; if you spot an error, add a dated, signed correction that leaves the original visible or, in electronic systems, use the audit-trailed amendment function. Backdating or rewriting records is a conduct issue and can amount to falsification. If you witnessed something, record it yourself; do not let one colleague write everyone\'s account, because independent accounts are stronger evidence and group-authored ones look coordinated.</p><h2>Third-party information</h2><p>Logs constantly touch other people: parents, siblings, other residents, visitors, professionals. Two rules help. First, record only what is necessary and relevant about third parties. Second, remember that when a person accesses their own records, third-party information is generally redacted unless the third party consents or it is reasonable to disclose without consent. Make redaction feasible by keeping each individual\'s record about them: in a children\'s home, an incident involving two children should be written in each child\'s file from that child\'s perspective, referring to the other by initials or in a way your service\'s procedure sets out, rather than copying one full account into both files. Never record gossip, speculation about families, or details of another resident\'s history in someone else\'s file.</p><h2>Subject access awareness</h2><p>Under the UK GDPR and the Data Protection Act 2018, people have a right of access to their personal data, usually free of charge and usually within one calendar month. Children can exercise this right themselves when they have sufficient understanding, and care leavers frequently request their childhood files. Nothing sharpens recording practice like reading files with a care leaver who is meeting their own history for the first time. Write every entry as if the person will read it, because one day they may. That does not mean sanitising; it means being accurate, fair, respectful and free of casual cruelty. It is also a reason to include the good moments, achievements, jokes and kindnesses, not only incidents, so the file tells the truth about a life rather than a catalogue of problems.</p><h2>Safeguarding records</h2><p>When recording a disclosure or safeguarding concern, use the person\'s exact words in quotation marks wherever possible, record the questions you asked, avoid leading questions in the conversation itself, note who you reported to and when, and keep the record factual to the point of plainness. These records may be evidence in criminal or family proceedings, and their value depends entirely on their precision. Follow your local procedures on where safeguarding records are stored and who may see them.</p><h2>Practical quality checks</h2><ul><li>Could a stranger reconstruct the event from my entry: who, what, when, where, who was told, what happened next?</li><li>Have I separated observation from interpretation, and labelled any opinion as mine with reasons?</li><li>Is every word one I could stand behind in front of the person, their family, an inspector and a judge?</li><li>Have I avoided abbreviations and jargon a future reader might not understand?</li><li>Is it signed or attributed, dated and timed?</li></ul><h2>Dos and don\'ts</h2><h3>Dos</h3><ul><li>Record facts: actions, direct quotes, times, places, people present and staff responses.</li><li>Label professional opinions as opinions and give the evidence behind them.</li><li>Write up promptly, and record both the time of the event and the time of writing.</li><li>Use the person\'s exact words for disclosures and significant statements.</li><li>Keep each person\'s file about them, and write third-party details so they can be redacted.</li><li>Include positives, progress and ordinary good days, not just incidents.</li><li>Correct errors transparently with dated amendments that preserve the original.</li></ul><h3>Don\'ts</h3><ul><li>Don\'t use labelling language such as attention-seeking, manipulative or kicked off.</li><li>Don\'t record gossip, speculation or other residents\' personal histories in someone\'s file.</li><li>Don\'t leave out what staff did, or write incidents with no follow-up or outcome.</li><li>Don\'t backdate, rewrite or delete records, or copy one colleague\'s account as everyone\'s.</li><li>Don\'t write anything you would be ashamed to read aloud to the person or a court.</li><li>Don\'t delay recording until details have blurred or handover rumours have coloured your memory.</li></ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('acas-early-conciliation-tribunal-deadlines', 'rights', 'Acas Early Conciliation and Tribunal Deadlines Explained', 'Most employment tribunal claims must start within three months less one day. Learn how Acas early conciliation works and how it pauses the deadline clock.', 'Employment tribunal deadlines are short and strict: most claims must be started within three months less one day. Before you can bring most claims you must notify Acas for early conciliation, which pauses the clock while you try to settle. This article explains the deadlines, how the pause works and what the certificate is for.', '["Employment Tribunals Act 1996, section 18A (early conciliation)","Employment Rights Act 1996 (time limits for unfair dismissal and deductions claims)","Equality Act 2010, section 123 (discrimination time limits)"]', '<h2>The basic deadline: three months less one day</h2>
<p>Most employment tribunal claims must be <strong>started within three months less one day</strong> of the event you are complaining about. For example:</p>
<ul>
<li><strong>Unfair dismissal:</strong> three months less one day from the effective date of termination, usually your last day of employment.</li>
<li><strong>Unlawful deductions from wages</strong> (including unpaid or underpaid wages, sleep-in allowances and holiday pay): three months less one day from the date of the payment the deduction was made from, or from the last in a series of deductions.</li>
<li><strong>Discrimination:</strong> three months less one day from the act complained of, or from the end of continuing conduct.</li>
</ul>
<p>A small number of claims have longer limits, notably <strong>statutory redundancy pay</strong> and <strong>equal pay</strong>, which are six months. Tribunals can extend deadlines only in narrow circumstances, and you should never rely on getting an extension. If in doubt, treat the three-month rule as fixed and check the current rules on <a href="https://www.gov.uk/employment-tribunals">gov.uk/employment-tribunals</a>, as time limits can be changed by legislation.</p>
<p>Two traps care staff often fall into: raising an internal <strong>grievance or appeal does not pause the deadline</strong>, and waiting for a final payslip or P45 does not either. The clock runs from the event itself.</p>
<h2>Early conciliation: a required first step</h2>
<p>Before you can present most tribunal claims, you must first <strong>notify Acas</strong> (the Advisory, Conciliation and Arbitration Service) under the early conciliation rules in section 18A of the Employment Tribunals Act 1996. This is free and you can do it online or by phone. See <a href="https://www.acas.org.uk/early-conciliation">acas.org.uk/early-conciliation</a>.</p>
<p>What happens next:</p>
<ol>
<li>You submit an early conciliation notification with your details and your employer\'s details. The date Acas receives it is called <strong>Day A</strong>.</li>
<li>A conciliator contacts you to discuss the dispute and, if you agree, contacts your employer to explore settlement. The early conciliation period can last <strong>up to six weeks</strong>.</li>
<li>Talking to the conciliator does not commit you to anything. You can settle, or you can end the process at any point and go to tribunal.</li>
<li>If no settlement is reached, or you decline conciliation, Acas issues an <strong>early conciliation certificate</strong> with a unique reference number. The date you are treated as receiving it is called <strong>Day B</strong>.</li>
</ol>
<p>You <strong>cannot submit a tribunal claim without a certificate number</strong> for each respondent you are claiming against; the tribunal will reject the claim form without it.</p>
<h2>How early conciliation pauses the clock</h2>
<p>The time you spend in early conciliation does not count towards your tribunal deadline. In outline:</p>
<ul>
<li>The period from the day after Day A to Day B is <strong>added on</strong> to your time limit, so the clock is effectively paused while Acas is involved.</li>
<li>If your original deadline would fall within one month of Day B, you get <strong>at least one month from Day B</strong> to present your claim.</li>
</ul>
<p>The rules produce exact dates that are easy to miscalculate, especially if you notify Acas close to the deadline or have more than one claim arising on different dates. Treat any calculation you do yourself as provisional, and get it checked by an adviser. The safest approach is simple: <strong>contact Acas early</strong>, well before the three months are close to running out.</p>
<h2>Which claims does this apply to?</h2>
<p>Early conciliation applies to the great majority of tribunal claims, including unfair dismissal, wage deductions, holiday pay, discrimination, whistleblowing detriment and redundancy pay. A few limited exceptions exist, but if you are a care worker with a pay, dismissal or discrimination dispute, you should assume the requirement applies to you.</p>
<h2>If you settle</h2>
<p>Settlements reached through Acas are recorded on a form called a <strong>COT3</strong> and are legally binding: you receive the agreed sum and give up the claims covered by the agreement. Take advice before signing, because a COT3 usually ends the matter for good. Settlement can also include an agreed reference, which is often valuable in social care recruitment.</p>
<h2>Key takeaways</h2>
<ul>
<li>Assume <strong>three months less one day</strong> for most claims, six months for redundancy pay and equal pay.</li>
<li>Grievances, appeals and negotiations <strong>do not pause the clock</strong>. Only early conciliation does.</li>
<li>Notify Acas <strong>as early as possible</strong> and keep your certificate number safe.</li>
<li>There is currently no fee to bring an employment tribunal claim.</li>
</ul>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for advice on deadlines and to ask about early conciliation, or start online at <a href="https://www.acas.org.uk/early-conciliation">acas.org.uk/early-conciliation</a>.</li>
<li><strong>Your trade union</strong>, which can advise on the merits of a claim and may provide legal representation.</li>
<li><strong>Citizens Advice</strong> for free help checking your deadline and completing forms.</li>
<li><strong>A solicitor or law centre</strong> for complex claims such as discrimination or whistleblowing, ideally before your deadline is close.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('emergency-tax-codes', 'rights', 'Emergency Tax Codes and How to Fix Them', 'Emergency tax codes like 1257L W1 or M1 can mean you pay too much tax in a new care job. Learn how to check your tax code and get it fixed with HMRC.', 'Starting a new care job, or juggling more than one, can land you on an emergency or incorrect tax code and leave you paying too much tax. This article explains what codes like 1257L W1/M1, 0T and BR mean, how to check your code, and how to get it corrected and any overpaid tax refunded.', '["Income Tax (Earnings and Pensions) Act 2003 (PAYE system)","Income Tax (Pay As You Earn) Regulations 2003"]', '<h2>What a tax code is</h2>
<p>Your tax code tells your employer\'s payroll how much income tax to take from your pay under PAYE (Pay As You Earn). It appears on your payslip, usually near your name or National Insurance number. If the code is wrong, the tax taken from your wages will be wrong, and in care work, where people often move between employers or hold several jobs at once, wrong codes are common.</p>
<p>The standard code for most people with one job is currently <strong>1257L</strong>. It means you get the standard tax-free Personal Allowance of 12,570 pounds spread evenly across the year. You can read more about how codes work at <a href="https://www.gov.uk/tax-codes">gov.uk/tax-codes</a>.</p>
<h2>Common emergency and non-standard codes</h2>
<table>
<tr><th>Code</th><th>What it means</th><th>Typical effect</th></tr>
<tr><td><strong>1257L W1, 1257L M1 or 1257L X</strong></td><td>An emergency, non-cumulative code. W1 means week 1, M1 means month 1. Each payday is taxed in isolation, ignoring the rest of the tax year.</td><td>You get a slice of your Personal Allowance each payday but no adjustment for earlier weeks or months, so refunds owed to you do not come through automatically.</td></tr>
<tr><td><strong>0T</strong></td><td>No Personal Allowance is applied at all, often because your employer does not have the information needed to give you a code.</td><td>Tax is taken from the first pound you earn. Often too much tax.</td></tr>
<tr><td><strong>BR</strong></td><td>All pay from this job is taxed at the basic rate of 20 per cent, with no allowance.</td><td>Normal and often correct for a <strong>second</strong> job, because your allowance is used against your main job. Usually wrong if applied to your only job.</td></tr>
</table>
<h2>Why care staff end up on emergency codes</h2>
<ul>
<li>You started a new job and did not give your new employer a <strong>P45</strong> from your last job.</li>
<li>You did not complete a <strong>starter checklist</strong> (the form that replaced the old P46) or the information on it was incomplete.</li>
<li>You work for more than one employer or agency, and HMRC has split or allocated your allowance in a way that no longer matches your earnings.</li>
<li>You moved from self-employment, from a period on benefits, or from study into employment.</li>
<li>You started receiving a workplace or private pension alongside earnings.</li>
</ul>
<p>An emergency code is meant to be temporary. It should be replaced once HMRC has matched your job to its records, but this does not always happen without a prompt.</p>
<h2>How to check your code</h2>
<ol>
<li><strong>Look at your payslip.</strong> Note the code and whether W1, M1 or X appears after it.</li>
<li><strong>Sign in to your personal tax account</strong> at <a href="https://www.gov.uk/personal-tax-account">gov.uk/personal-tax-account</a> or use the HMRC app. You can see every job and pension HMRC has on record for you, the code for each, and an estimate of the tax you will pay.</li>
<li><strong>Check the jobs listed are right.</strong> A very common problem for care staff is an old employer still showing as live, which can leave your allowance attached to a job you no longer have.</li>
</ol>
<h2>How to fix it</h2>
<ul>
<li><strong>Give your new employer your P45</strong> from your previous job as soon as you can. If you do not have one, ask to complete a starter checklist and answer it accurately, especially the question about other jobs.</li>
<li><strong>Update your details online.</strong> In your personal tax account you can tell HMRC that a job has ended, that estimated pay is wrong, or that allowances should be moved between jobs.</li>
<li><strong>Phone HMRC</strong> on 0300 200 3300 (Income Tax enquiries) if you cannot fix it online. Have your National Insurance number and payslips to hand.</li>
<li><strong>Your employer cannot change your code themselves.</strong> Payroll must use the code HMRC issues, so the fix always goes through HMRC, but once the corrected code arrives your employer must apply it.</li>
</ul>
<h2>Getting overpaid tax back</h2>
<p>Once HMRC issues a corrected cumulative code, any tax you have overpaid in the current tax year is usually refunded automatically through your wages over the following paydays. If the overpayment relates to a previous tax year, HMRC will normally send a calculation (a P800) and you can claim online. See <a href="https://www.gov.uk/claim-tax-refund">gov.uk/claim-tax-refund</a>. If you stopped working part-way through a year, you may also be able to claim an in-year refund.</p>
<p>Keep your payslips and P45s. They are your evidence if the figures need correcting later.</p>
<h2>Where to get help</h2>
<ul>
<li><strong>HMRC Income Tax helpline</strong> on 0300 200 3300, or your <a href="https://www.gov.uk/personal-tax-account">personal tax account</a> online, for anything to do with your tax code or a refund.</li>
<li><strong>Citizens Advice</strong> can help you understand deductions and deal with HMRC if you are struggling.</li>
<li><strong>Your union</strong> can help if your employer is applying codes incorrectly or delaying refunds through payroll.</li>
<li><strong>Acas helpline</strong> on 0300 123 1100 if a tax code problem has turned into a dispute with your employer about pay.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('payslips-what-to-check', 'rights', 'Your Right to a Payslip and What to Check on It', 'Every employee and worker has the right to an itemised payslip. Find out what your payslip must show, and how to spot and fix errors in your care pay.', 'Everyone classed as an employee or worker has a legal right to an itemised payslip on or before payday. This article explains what your payslip must show under the Employment Rights Act 1996, including hours worked where your pay varies, and how to check it for common errors in social care pay.', '["Employment Rights Act 1996, section 8 (itemised pay statements)","Employment Rights Act 1996 (Itemised Pay Statement) (Amendment) Order 2018","National Minimum Wage Act 1998","Employment Rights Act 1996, section 13 (unlawful deductions from wages)"]', '<h2>Your legal right to a payslip</h2>
<p>If you are an employee or a worker, you have the right to a written, itemised payslip on or before every payday. This right comes from <a href="https://www.legislation.gov.uk/ukpga/1996/18/section/8">section 8 of the Employment Rights Act 1996</a>. Since 6 April 2019, the right covers workers as well as employees, so it includes most agency staff, bank staff and casual care workers.</p>
<p>Your payslip can be on paper or electronic (for example, through a payroll portal), but your employer must give you a way to see it by payday.</p>
<h2>What your payslip must show</h2>
<p>By law, every payslip must show:</p>
<ul>
<li>your <strong>gross pay</strong> (pay before any deductions)</li>
<li>the <strong>amounts of any variable deductions</strong>, such as income tax and National Insurance, and what they are for</li>
<li>the <strong>amounts of any fixed deductions</strong>, such as union subscriptions, and what they are for (or a separate standing statement of fixed deductions)</li>
<li>your <strong>net pay</strong> (take-home pay)</li>
<li>where different parts of your net pay are paid in different ways, the <strong>amount and method of each part</strong></li>
</ul>
<p>Since 6 April 2019, if your pay varies depending on how much time you have worked, your payslip must also show the <strong>number of hours you are being paid for</strong>. This can be shown as a single total or broken down by rate, for example day hours, night hours and sleep-in shifts. This matters a great deal in social care, where many staff are paid hourly and work variable rotas.</p>
<h2>What to check every payday</h2>
<h3>1. Hours and rates</h3>
<p>Check the hours on your payslip against your rota, timesheets or the shifts you actually worked, including any extra shifts, overtime and handover time you were required to work. Check each rate of pay matches your contract, and check enhancements for nights, weekends or bank holidays if your contract provides them.</p>
<h3>2. National Minimum Wage</h3>
<p>Divide your total pay for the pay period by the hours you worked. Your average must not fall below the <a href="https://www.gov.uk/national-minimum-wage-rates">current National Minimum Wage or National Living Wage rate</a> for your age. Watch out for things that can quietly pull care workers below the minimum wage, such as unpaid travel time between home care visits, unpaid training, or deductions for uniforms and DBS checks. Deductions for items connected with your job can reduce your pay for minimum wage purposes even if you agreed to them.</p>
<h3>3. Tax code and National Insurance</h3>
<p>Check the tax code shown on your payslip. If it looks wrong, or ends in W1, M1 or X, you may be on an emergency code and paying too much tax. You can check your code through your <a href="https://www.gov.uk/personal-tax-account">personal tax account</a>.</p>
<h3>4. Deductions</h3>
<p>Under <a href="https://www.legislation.gov.uk/ukpga/1996/18/section/13">section 13 of the Employment Rights Act 1996</a>, your employer can normally only make deductions that are required by law (tax, National Insurance, court orders), allowed by your contract, or that you have agreed to in writing <strong>before</strong> the deduction is made. Query anything you do not recognise, such as charges for training, DBS checks, uniforms or alleged overpayments.</p>
<h3>5. Pension</h3>
<p>If you are enrolled in a workplace pension, check that both your contribution and any employer contribution appear and look consistent from month to month.</p>
<h3>6. Holiday pay</h3>
<p>If you are paid for annual leave, check that holiday pay reflects your normal pay, including regular overtime and enhancements where these are a settled part of your earnings.</p>
<h2>If something is wrong or you get no payslip</h2>
<ol>
<li><strong>Keep evidence.</strong> Save your rotas, timesheets, shift confirmations and payslips.</li>
<li><strong>Raise it early.</strong> Ask your manager or payroll team to explain or correct the error in writing. Most payslip problems are genuine mistakes and are fixed quickly.</li>
<li><strong>Put it in writing.</strong> If it is not resolved, raise a formal grievance following your employer\'s procedure.</li>
<li><strong>Enforce your rights.</strong> If your employer does not give you a payslip, or the payslip does not show what the law requires, you can ask an employment tribunal for a declaration. Unlawful deductions and underpayment of wages can also be claimed in a tribunal, and strict time limits apply, usually three months less one day from the deduction. See <a href="https://www.gov.uk/employment-tribunals">gov.uk guidance on employment tribunals</a>.</li>
</ol>
<p>You can read the government\'s plain-English overview of payslip rights at <a href="https://www.gov.uk/payslips">gov.uk/payslips</a>.</p>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for free, confidential advice on pay and payslip rights, or visit <a href="https://www.acas.org.uk/">acas.org.uk</a>.</li>
<li><strong>HMRC</strong> if you think you are being paid below the minimum wage: <a href="https://www.gov.uk/minimum-wage-complaint">complain about National Minimum Wage underpayment</a>. You can complain confidentially, even about a previous employer.</li>
<li><strong>Your trade union</strong>, if you are a member, can check your payslips and raise issues on your behalf.</li>
<li><strong>Citizens Advice</strong> for free help understanding deductions and pursuing unpaid wages.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('raising-a-grievance', 'rights', 'Raising a Grievance Step by Step', 'A step-by-step guide to raising a grievance at work, from informal conversations to written grievances, meetings and appeals under the Acas Code.', 'A grievance is a formal way to raise a problem at work, such as pay errors, unsafe staffing, bullying or unfair treatment. This article walks through the process step by step, from trying to resolve things informally to the written grievance, the meeting, your right to be accompanied and the appeal.', '["Acas Code of Practice on Disciplinary and Grievance Procedures","Employment Relations Act 1999, section 10 (right to be accompanied)","Trade Union and Labour Relations (Consolidation) Act 1992, section 207A (adjustment of tribunal awards)"]', '<h2>What a grievance is</h2>
<p>A grievance is a concern, problem or complaint that you raise formally with your employer. In social care, common grievances include pay and payslip errors, rota and hours disputes, unsafe staffing levels, lack of supervision or training, bullying or harassment, and unfair treatment. You do not need anyone\'s permission to raise a grievance, and you must not be punished for raising one in good faith.</p>
<p>The standards employers are expected to follow are set out in the <a href="https://www.acas.org.uk/acas-code-of-practice-on-disciplinary-and-grievance-procedures">Acas Code of Practice on Disciplinary and Grievance Procedures</a>. The Code is not itself law, but employment tribunals must take it into account, and can adjust compensation by up to 25 per cent if you or your employer unreasonably fail to follow it. Your employer should also have its own written grievance procedure. Ask for a copy or find it in your staff handbook.</p>
<h2>Step 1: try to resolve it informally</h2>
<p>Most problems are best solved with a conversation. Ask your line manager for a private word, explain the issue calmly and say what would put it right. Take notes of the date and what was agreed. If your manager is the problem, speak to another manager or HR. Informal resolution is quicker and less stressful, and tribunals expect you to have given it a fair chance where practical, but you are not required to keep trying informally if it is not working or the issue is serious.</p>
<h2>Step 2: put your grievance in writing</h2>
<p>If informal routes fail, write to the person named in your employer\'s procedure (often your manager or HR). Keep a copy. Your letter or email should:</p>
<ul>
<li>say clearly that it is a <strong>formal grievance</strong></li>
<li>set out the facts: what happened, when, where and who was involved</li>
<li>attach or list your <strong>evidence</strong>, such as rotas, payslips, messages and names of witnesses</li>
<li>explain the <strong>outcome you want</strong>, for example back pay, a rota change or action to stop bullying</li>
</ul>
<p>Stick to facts and avoid insults or exaggeration. A short, clear, dated account is far more powerful. Government guidance is at <a href="https://www.gov.uk/raise-grievance-at-work">gov.uk/raise-grievance-at-work</a>.</p>
<h2>Step 3: the grievance meeting</h2>
<p>Your employer should invite you to a meeting <strong>without unreasonable delay</strong> to discuss your grievance. At the meeting:</p>
<ul>
<li>explain your grievance and how you think it should be resolved</li>
<li>answer questions honestly and refer to your evidence</li>
<li>take your own notes, or ask your companion to</li>
</ul>
<p>The employer may need to adjourn to investigate, for example to check records or speak to witnesses. That is normal and usually a good sign that it is being taken seriously.</p>
<h2>Your right to be accompanied</h2>
<p>Under <a href="https://www.legislation.gov.uk/ukpga/1999/26/section/10">section 10 of the Employment Relations Act 1999</a>, you have the right to be accompanied at a grievance hearing by a <strong>trade union representative or a work colleague</strong>, where the grievance concerns a duty your employer owes you, which covers most real grievances. You must make a reasonable request. Your companion can present your case, sum it up and confer with you, though they cannot answer questions on your behalf. If your chosen companion is unavailable, you can ask to postpone the hearing to a reasonable alternative time within five working days.</p>
<h2>Step 4: the decision</h2>
<p>After the meeting and any investigation, your employer should give you a <strong>written decision</strong> without unreasonable delay, telling you what it has decided, what action it will take and how to appeal. If your grievance is upheld, make sure the promised action actually happens, and keep the decision letter.</p>
<h2>Step 5: the appeal</h2>
<p>If you are unhappy with the decision, appeal in writing within the deadline in your employer\'s procedure, saying which findings you disagree with and why. The appeal should be heard, wherever possible, by a more senior manager who was not involved in the original decision, and you have the same right to be accompanied. The appeal outcome should also be in writing.</p>
<h2>Practical points to remember</h2>
<ul>
<li><strong>Keep records of everything:</strong> dates, copies, notes of meetings and who said what.</li>
<li><strong>Grievances do not stop the tribunal clock.</strong> Most tribunal claims must start within three months less one day of the event, and raising a grievance does not pause that deadline. If your issue could become a claim, start Acas early conciliation in time even if the grievance is still running.</li>
<li><strong>You are protected</strong> from victimisation for raising concerns about discrimination and from detriment for whistleblowing about care standards.</li>
<li><strong>Consider mediation.</strong> Acas and many employers offer mediation, which can work well for relationship problems between colleagues.</li>
</ul>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for free, impartial advice at any stage, and the full Code at <a href="https://www.acas.org.uk/acas-code-of-practice-on-disciplinary-and-grievance-procedures">acas.org.uk</a>.</li>
<li><strong>Your trade union representative</strong>, who can help draft the grievance and accompany you at hearings.</li>
<li><strong>Citizens Advice</strong> for free help if you are not in a union.</li>
<li><strong>HR or a senior manager</strong> in your organisation, particularly where your line manager is part of the problem.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('references-what-employers-can-say', 'rights', 'References: What Employers Can and Cannot Say', 'Employers do not usually have to give you a reference, but any reference must be accurate and fair. Know your rights when moving between social care jobs.', 'Most employers have no general legal duty to provide a reference, but in social care recruitment your work history and conduct will almost always be checked. This article explains when references must be given, the legal duty to make them true, accurate and fair, and what you can do about a misleading reference.', '["Spring v Guardian Assurance plc [1995] 2 AC 296 (duty of care in references)","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, regulation 19 and Schedule 3","Equality Act 2010, section 108 (post-employment discrimination and victimisation)","Data Protection Act 2018 and UK GDPR"]', '<h2>Does my employer have to give me a reference?</h2>
<p>In most jobs, <strong>no</strong>. There is no general legal duty on an employer to provide a reference for a current or former member of staff, however long you worked there. A small number of exceptions exist, for example in some financial services roles, and an employer may be contractually bound to provide one if a settlement agreement says so.</p>
<p>Social care sits in a special position. Because of <strong>safer recruitment</strong> rules, a care provider recruiting you is required to check your character and conduct. Under <a href="https://www.legislation.gov.uk/uksi/2014/2936/regulation/19">regulation 19</a> and Schedule 3 of the Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, CQC-registered providers must obtain satisfactory evidence of your conduct in previous health or social care employment, and the reason you left any job that involved working with children or vulnerable adults. Similar expectations apply in children\'s services and are inspected by Ofsted. In practice, this means your previous care employers will be asked for a <strong>conduct reference</strong>, and regulators expect providers to respond, so an outright refusal to say anything at all is unusual in this sector.</p>
<h2>If a reference is given, it must be accurate and fair</h2>
<p>The key legal protection comes from the House of Lords decision in <strong>Spring v Guardian Assurance plc [1995]</strong>. An employer that gives a reference owes you a <strong>duty of care</strong>. The reference must be:</p>
<ul>
<li><strong>true and accurate</strong> in its facts</li>
<li><strong>fair overall</strong>, not giving a misleading impression through selective or one-sided content</li>
<li>based on matters the employer has reasonable grounds to believe, not rumour or unresolved suspicion presented as fact</li>
</ul>
<p>If a careless, inaccurate or misleadingly unfair reference costs you a job, you may be able to claim compensation for negligent misstatement. The same duty of care is owed to the recruiting employer, which is why sensible referees stick to what they can evidence.</p>
<h2>What employers can legitimately include</h2>
<ul>
<li><strong>Factual details:</strong> your dates of employment, job title and duties. Many employers now give short, factual-only references as a matter of policy, and that is lawful.</li>
<li><strong>Performance and conduct:</strong> opinions are allowed if honestly held and based on accurate facts, for example a recorded disciplinary outcome.</li>
<li><strong>Disciplinary and safeguarding matters:</strong> concluded findings can be mentioned if accurate. Live, uninvestigated allegations are dangerous territory for a referee and should not be presented as established fact. In safer recruitment, however, employers are expected to answer honestly when asked about conduct, safeguarding concerns and reasons for leaving, so serious concluded matters may lawfully appear.</li>
<li><strong>Sickness absence and health:</strong> asking about health before a job offer is restricted by the Equality Act 2010, and references should not be used as a back door to health information. Disability-related content can amount to discrimination.</li>
</ul>
<h2>What employers cannot do</h2>
<ul>
<li>Give a reference they know to be <strong>false or misleading</strong>. This could also mislead the new employer and, in a care setting, put people at risk.</li>
<li>Use a bad reference to <strong>punish you</strong> for raising a discrimination complaint or whistleblowing. Post-employment victimisation is unlawful under <a href="https://www.legislation.gov.uk/ukpga/2010/15/section/108">section 108 of the Equality Act 2010</a>, and detriment for protected disclosures is also unlawful.</li>
<li>Deliberately give a glowing reference that conceals known safeguarding concerns. In safer recruitment this can have serious consequences for the referee.</li>
</ul>
<h2>Can I see what was written about me?</h2>
<p>Data protection law gives you a right of access to your personal data, but there is a specific exemption for confidential employment references in the Data Protection Act 2018, which can apply both to the employer that gave the reference and the one that received it. In practice, some employers will still share references on request, and inaccurate personal data can be challenged under UK GDPR accuracy rules, so it is always worth asking.</p>
<h2>If a reference is holding you back</h2>
<ol>
<li>Ask the new employer what the concern is. They do not have to tell you, but many will give an indication.</li>
<li>Ask your former employer, in writing, to review or correct the reference, setting out the facts you say are wrong.</li>
<li>Consider offering alternative referees, such as a previous manager who knows your work well.</li>
<li>Get advice on legal options: negligent misstatement, victimisation or discrimination claims all have strict time limits.</li>
</ol>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for advice on references and job offers withdrawn after a reference, or see the references guidance at <a href="https://www.acas.org.uk/">acas.org.uk</a>.</li>
<li><strong>Your trade union</strong>, which can challenge an unfair reference on your behalf and support you in any settlement negotiation over an agreed reference.</li>
<li><strong>Citizens Advice</strong> for free help understanding your options.</li>
<li><strong>A solicitor</strong> if a misleading reference has cost you a job, as negligence and discrimination claims can be complex.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('resignation-constructive-dismissal-basics', 'rights', 'Resignation and Constructive Dismissal Basics', 'Thinking of resigning over how you have been treated at work? Understand the basics of constructive dismissal and why you should always get advice first.', 'Constructive dismissal is when you resign in response to a fundamental breach of contract by your employer, such as not paying you or destroying trust and confidence. These claims are hard to win and resigning is a serious step, so this article covers the basics and signposts you strongly to advice before you act.', '["Employment Rights Act 1996, sections 95(1)(c) and 108 (constructive dismissal and qualifying service)","Western Excavating (ECC) Ltd v Sharp [1978] ICR 221","Employment Rights Act 1996, section 86 (minimum notice periods)"]', '<p><strong>Important:</strong> this article is general information, not legal advice. Resigning is one of the most serious steps you can take at work and can rarely be undone. <strong>Speak to Acas, your union or a solicitor before you resign</strong>, however bad things feel today.</p>
<h2>What constructive dismissal means</h2>
<p>Normally, if you resign, you have not been dismissed and cannot claim unfair dismissal. <strong>Constructive dismissal</strong> is the exception. Under <a href="https://www.legislation.gov.uk/ukpga/1996/18/section/95">section 95(1)(c) of the Employment Rights Act 1996</a>, you are treated as dismissed if you resign, with or without notice, in circumstances where your employer\'s conduct entitled you to leave.</p>
<p>The test comes from <strong>Western Excavating (ECC) Ltd v Sharp [1978]</strong>. You must show:</p>
<ol>
<li>your employer committed a <strong>fundamental (repudiatory) breach</strong> of your contract, going to the root of the employment relationship;</li>
<li>you resigned <strong>in response to that breach</strong>, not mainly for another reason; and</li>
<li>you did not delay too long, otherwise you may be treated as having <strong>affirmed</strong> the contract and accepted the situation.</li>
</ol>
<h2>What counts as a fundamental breach</h2>
<p>It must be serious. Ordinary unfairness, annoyance or poor management is not enough. Examples that have founded claims include:</p>
<ul>
<li>not paying wages, or unilaterally cutting pay or hours without agreement</li>
<li>demotion or major changes to your role imposed without any contractual right</li>
<li>serious failures to deal with bullying, harassment or unsafe working conditions, which in care settings can include persistently dangerous staffing levels after concerns are raised</li>
<li>conduct destroying the implied term of <strong>mutual trust and confidence</strong>, such as humiliating treatment, false accusations or a wholly unfair disciplinary process</li>
</ul>
<p>A series of smaller incidents can add up, with a final incident acting as the last straw, but the overall course of conduct must still amount to a fundamental breach.</p>
<h2>Why acting promptly matters, and why rushing is dangerous</h2>
<p>There is a genuine tension here, which is exactly why you need advice:</p>
<ul>
<li>If you <strong>carry on working for months</strong> as if nothing happened, a tribunal may decide you affirmed the contract and lost the right to resign over the breach.</li>
<li>If you <strong>resign in the heat of the moment</strong>, you give up your income, and possibly your notice pay and eligibility for some benefits, on a claim that is notoriously difficult to win. You carry the burden of proving the breach.</li>
</ul>
<p>Middle paths exist. You can raise a grievance while making clear in writing that you are <strong>working under protest</strong> and not accepting the change. Working under protest for a short period while the grievance is heard will not necessarily count as affirmation, but the longer things drift, the weaker your position, so take advice quickly rather than either resigning or silently soldiering on.</p>
<h2>Qualifying service and time limits</h2>
<ul>
<li>Constructive unfair dismissal claims normally require <strong>two years\' continuous service</strong> with the employer, under section 108 of the Employment Rights Act 1996. Important exceptions need no qualifying service, including dismissals connected with whistleblowing, health and safety concerns, discrimination and asserting statutory rights. The rules on qualifying service are subject to change, so check the current position with Acas before relying on it.</li>
<li>The tribunal deadline is <strong>three months less one day</strong> from the date your employment ends, and you must go through <a href="https://www.acas.org.uk/early-conciliation">Acas early conciliation</a> first.</li>
<li>Separate contract claims, for example for notice pay (wrongful dismissal), can sometimes run alongside.</li>
</ul>
<h2>Practical basics if you do resign</h2>
<ul>
<li><strong>Get advice first.</strong> One conversation with Acas, your union or a solicitor can change the whole outcome.</li>
<li><strong>Resign in writing</strong> and state the reason. A resignation letter that says nothing, or thanks everyone warmly, will be quoted back at you later.</li>
<li><strong>Check your notice.</strong> The statutory minimum you must give is one week after a month\'s service (<a href="https://www.legislation.gov.uk/ukpga/1996/18/section/86">section 86, Employment Rights Act 1996</a>), but your contract may require more. In a fundamental breach situation you may be entitled to resign without notice, but take advice before doing so. See <a href="https://www.gov.uk/handing-in-your-notice">gov.uk/handing-in-your-notice</a>.</li>
<li><strong>Keep your evidence:</strong> the grievance, emails, rotas, payslips and notes of incidents, gathered lawfully.</li>
<li><strong>Think about references and regulation.</strong> In social care your next employer will seek a conduct reference, so how you leave matters.</li>
</ul>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100, free and confidential, before you make any decision, and for early conciliation if you have already left: <a href="https://www.acas.org.uk/">acas.org.uk</a>.</li>
<li><strong>Your trade union</strong>, which can advise on the strength of your position and may fund legal representation.</li>
<li><strong>An employment solicitor or law centre</strong> for advice on the merits before you resign. Many offer a fixed-fee first meeting, and this is one situation where paying for an hour of advice can be the best money you ever spend.</li>
<li><strong>Citizens Advice</strong> for free help with your options, benefits implications and next steps.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('secondary-employment-48-hour-week', 'rights', 'Secondary Employment and the 48-Hour Week', 'If you work more than one care job, the 48-hour weekly limit applies to your total hours. Understand the Working Time Regulations and your opt-out rights.', 'Many care staff hold more than one job, often mixing contracted hours with bank or agency shifts. This article explains how the 48-hour average weekly limit in the Working Time Regulations 1998 applies across all your jobs added together, how the voluntary opt-out works, and why you should be open with each employer about your total hours.', '["Working Time Regulations 1998 (SI 1998/1833), regulations 4 and 5","Working Time Regulations 1998, regulations 10 to 12 (rest breaks and rest periods)","Employment Rights Act 1996, section 45A (protection from detriment)"]', '<h2>The 48-hour limit in brief</h2>
<p>Under regulation 4 of the <a href="https://www.legislation.gov.uk/uksi/1998/1833/contents">Working Time Regulations 1998</a>, adult workers must not work more than an average of <strong>48 hours a week</strong>, normally averaged over a <strong>17-week reference period</strong>. The limit exists for health and safety reasons: tired workers make mistakes, and in care work those mistakes can harm the people you support as well as you.</p>
<p>The official overview is at <a href="https://www.gov.uk/maximum-weekly-working-hours">gov.uk/maximum-weekly-working-hours</a>.</p>
<h2>The limit applies to all your jobs added together</h2>
<p>This is the point care staff most often miss. The 48-hour average applies to your <strong>total working time</strong>, not to each job separately. If you work 30 hours for a care home and regularly pick up 25 hours of agency shifts, you are over the limit even though neither job alone comes close to it.</p>
<p>Working time generally includes:</p>
<ul>
<li>time spent working at your employer\'s disposal and carrying out your duties, including handovers</li>
<li>job-related training</li>
<li>working travel, such as travel between home care visits (though not your ordinary commute)</li>
</ul>
<p>It does not usually include unpaid rest breaks or time you are entirely free to use as your own.</p>
<h2>What each employer must do</h2>
<p>Each of your employers must take <strong>all reasonable steps</strong> to make sure the 48-hour limit is complied with for you. That is why many care contracts require you to tell your employer about secondary employment and to get agreement before taking another job or regular bank work elsewhere. This is not just paperwork:</p>
<ul>
<li>Employers cannot manage the limit without knowing your total hours, so honesty protects everyone, including your registration and reputation if something goes wrong on shift.</li>
<li>An employer can reasonably refuse or limit secondary work where your combined hours would breach the limit or create fatigue risks, but it should act proportionately.</li>
<li>Hiding a second job when your contract requires disclosure can be a disciplinary matter, so it is always better to declare it.</li>
</ul>
<h2>The opt-out: your choice, not your employer\'s</h2>
<p>Regulation 5 allows you to <strong>opt out</strong> of the 48-hour limit by signing a written agreement. Key points:</p>
<ul>
<li>The opt-out must be <strong>voluntary and individual</strong>. It cannot be buried in a staff handbook and imposed on everyone, and you cannot be forced to sign one as a condition of getting shifts.</li>
<li>You can <strong>cancel it at any time</strong> by giving notice. The default notice is 7 days; your agreement can set a longer period, but no more than 3 months.</li>
<li>Your employer must not dismiss you or subject you to a detriment (such as dropping your shifts) because you refuse to opt out or you cancel an opt-out. You would have tribunal claims if this happened.</li>
<li>An opt-out removes the 48-hour cap, but it does <strong>not</strong> remove your rest rights, and it does not make endless hours safe. Fatigue remains a professional and safeguarding issue.</li>
</ul>
<h2>Rights you cannot opt out of</h2>
<p>Whatever you sign, you keep the right to:</p>
<ul>
<li><strong>11 hours\' rest in each 24-hour period</strong></li>
<li><strong>24 hours\' uninterrupted rest each week</strong> (or 48 hours each fortnight)</li>
<li>a <strong>20-minute rest break</strong> when working more than 6 hours</li>
<li>limits on <strong>night work</strong>, normally an average of 8 hours in 24 for night workers, plus free health assessments</li>
</ul>
<p>In residential care and similar continuous services, employers can sometimes vary the timing of rest under the special-case rules, but they must then give you <strong>equivalent compensatory rest</strong>. Back-to-back shifts across two employers can quietly destroy your daily rest, which is another reason total hours need to be visible to someone.</p>
<h2>Young workers</h2>
<p>If you are under 18, stricter rules apply: normally no more than <strong>8 hours a day and 40 hours a week across all jobs</strong>, with no adult-style opt-out available, plus longer rest entitlements.</p>
<h2>Practical steps if your hours are a problem</h2>
<ol>
<li>Add up your average weekly hours across every job over the last 17 weeks.</li>
<li>If you are over 48 and have not opted out, tell your employers. They must help bring your hours down; you should not simply be blamed.</li>
<li>If you have opted out but the hours are harming your health, cancel the opt-out in writing and keep a copy.</li>
<li>If you suffer a detriment for refusing to opt out, get advice quickly, as tribunal time limits are short.</li>
</ol>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for advice on working time, opt-outs and rest rights, or see the working hours guidance at <a href="https://www.acas.org.uk/">acas.org.uk</a>.</li>
<li><strong>Health and Safety Executive (HSE)</strong>, which enforces the working time limits (as opposed to rest entitlements, which you enforce through a tribunal).</li>
<li><strong>Your trade union</strong> for support challenging rotas or pressure to opt out.</li>
<li><strong>Citizens Advice</strong> for free help if excessive hours are tied up with pay or contract problems.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('sleep-in-pay-explained', 'rights', 'Sleep-In Pay Explained', 'Sleep-in shifts are paid differently from waking nights. Understand the Mencap Supreme Court ruling, minimum wage rules and how to check your sleep-in pay.', 'Sleep-in shifts are a normal part of residential care, but the pay rules confuse many staff. This article explains the Supreme Court\'s decision in Mencap v Tomlinson-Blake, when the minimum wage applies during a sleep-in, the difference between contractual pay and the legal minimum, and how to check you are being paid correctly.', '["National Minimum Wage Act 1998","National Minimum Wage Regulations 2015","Royal Mencap Society v Tomlinson-Blake [2021] UKSC 8","Working Time Regulations 1998"]', '<h2>What a sleep-in shift is</h2>
<p>A sleep-in is a night shift where you stay at or near your workplace, usually a children\'s home, care home or supported living service, and are <strong>expected to sleep</strong> for most of the shift. You are given somewhere to sleep and you get up only if you are needed, for example if a resident is unwell or distressed. A sleep-in is different from a <strong>waking night</strong>, where you are expected to be awake and working for the whole shift.</p>
<h2>The Mencap case: what the Supreme Court decided</h2>
<p>For years there was uncertainty about whether every hour of a sleep-in counted for National Minimum Wage (NMW) purposes. The Supreme Court settled the question in <strong>Royal Mencap Society v Tomlinson-Blake [2021] UKSC 8</strong>.</p>
<p>The court decided that where a worker is expected to sleep during the shift and is merely <strong>available for work</strong>, the hours spent asleep or resting do <strong>not</strong> count as work for minimum wage purposes. Only the time you are <strong>awake for the purposes of working</strong>, for example when you get up to attend to a resident, counts towards the minimum wage calculation.</p>
<p>Two important points follow:</p>
<ul>
<li>The decision is about the <strong>legal minimum</strong> under the <a href="https://www.legislation.gov.uk/uksi/2015/621/contents">National Minimum Wage Regulations 2015</a>. It does not stop employers paying more, and many do.</li>
<li>The outcome is <strong>fact-specific</strong>. If you are actually expected to work through the night and are only permitted to nap when things are quiet, you may be working, not merely available, and the whole shift may count. Genuine waking nights always count in full.</li>
</ul>
<h2>Contractual pay versus the legal minimum</h2>
<p>Your pay for sleep-ins is set first by your <strong>contract</strong>, and the minimum wage acts as a floor underneath it. Typical arrangements in social care include:</p>
<ul>
<li>a <strong>flat sleep-in allowance</strong> for the night, sometimes with a set number of hours\' pay if you are disturbed</li>
<li>an <strong>hourly rate for time spent up and working</strong> during the night, on top of the allowance</li>
<li>in some organisations, <strong>full hourly pay for the whole sleep-in</strong>, often agreed with unions or required by commissioners</li>
</ul>
<p>Check your contract, your employer\'s sleep-in policy and anything agreed collectively with a union. If your employer has promised a particular allowance or rate, that promise is enforceable as a contractual right even though the NMW does not require it.</p>
<h2>Checking your sleep-in pay</h2>
<ol>
<li><strong>Read your contract and rota codes.</strong> Confirm whether a night is classed as a sleep-in or a waking night, and what the stated pay is for each.</li>
<li><strong>Record disturbances.</strong> Keep your own note of every time you were up and working: when you got up, what you did, when you returned to bed. Your employer should have a log too, but your own record is valuable evidence.</li>
<li><strong>Check the minimum wage arithmetic.</strong> For each pay reference period (usually a week or a month), your total NMW pay divided by your NMW hours, including time awake and working on sleep-ins, must not fall below the <a href="https://www.gov.uk/national-minimum-wage-rates">current rate for your age</a>. Frequent disturbances can tip a poorly paid sleep-in below the floor.</li>
<li><strong>Query mismatches in writing.</strong> If disturbed hours are not being added to your pay, raise it with payroll and your manager, and keep copies.</li>
</ol>
<h2>Sleep-ins and working time</h2>
<p>Minimum wage law and the <a href="https://www.legislation.gov.uk/uksi/1998/1833/contents">Working Time Regulations 1998</a> are separate regimes. Time on site on a sleep-in can still be relevant to your rest entitlements and overall working patterns even where it does not attract the minimum wage, so an employer cannot treat sleep-ins as if they were free time for rota purposes. If sleep-ins are stacked against day shifts in a way that leaves you exhausted, raise it as a health and safety concern.</p>
<h2>If you think you are being underpaid</h2>
<ul>
<li>Raise it internally first, with evidence, through your manager or a formal grievance.</li>
<li>You can complain to <strong>HMRC</strong>, which enforces the minimum wage, at <a href="https://www.gov.uk/minimum-wage-complaint">gov.uk/minimum-wage-complaint</a>. Complaints are confidential and can cover a previous employer.</li>
<li>Unpaid contractual sleep-in allowances can be claimed as unlawful deductions from wages in an employment tribunal, subject to strict time limits, normally three months less one day from the underpayment.</li>
</ul>
<h2>Where to get help</h2>
<ul>
<li><strong>Acas helpline</strong> on 0300 123 1100 for free advice on sleep-in pay, night work and how to raise a dispute, or visit <a href="https://www.acas.org.uk/">acas.org.uk</a>.</li>
<li><strong>HMRC</strong> for National Minimum Wage complaints: <a href="https://www.gov.uk/minimum-wage-complaint">gov.uk/minimum-wage-complaint</a>.</li>
<li><strong>Your trade union</strong>, which may already have a collective agreement on sleep-in rates where you work.</li>
<li><strong>Citizens Advice</strong> for help calculating what you are owed and pursuing it.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);
INSERT INTO articles (slug, section, title, meta_description, summary, key_legislation, body_html, status, review_due, published_at) VALUES ('supervision-entitlements', 'rights', 'Supervision Entitlements in Regulated Care Settings', 'Regular supervision is a regulatory requirement in registered care services. Learn what the rules say, what it should cover and what to do without it.', 'If you work in a registered care setting, your employer is required by regulation to make sure you receive appropriate supervision. This article explains the rules for children\'s homes and CQC-registered adult services, what good supervision should cover, and the steps to take if you are not getting it.', '["Children\'s Homes (England) Regulations 2015, regulation 33","Health and Social Care Act 2008 (Regulated Activities) Regulations 2014, regulation 18","Public Interest Disclosure Act 1998 (whistleblowing protection)"]', '<h2>Why supervision matters</h2>
<p>Supervision is protected time with a manager or senior colleague to reflect on your practice, discuss the people you support, raise concerns and plan your development. In social care it is not a luxury. It is one of the main safeguards for the people you care for, and one of the main supports for your own wellbeing and professional growth. In registered settings it is also a regulatory requirement, which means your employer can be held to account by an inspectorate if it does not happen.</p>
<h2>Children\'s homes: what the regulations say</h2>
<p>If you work in a children\'s home in England, <a href="https://www.legislation.gov.uk/uksi/2015/541/regulation/33">regulation 33 of the Children\'s Homes (England) Regulations 2015</a> applies. The registered person must ensure that all employees:</p>
<ul>
<li>undertake appropriate <strong>continuing professional development</strong></li>
<li>receive <strong>practice-related supervision</strong> by a person with appropriate experience</li>
<li>have their performance and fitness to perform their roles <strong>appraised at least once a year</strong></li>
</ul>
<p>The Guide to the Children\'s Homes Regulations, including the quality standards, sets the expectation that supervision supports safe, consistent care and is linked to the home\'s workforce plan. Ofsted inspects against these requirements, and poor supervision arrangements are a common inspection finding in homes that are struggling.</p>
<h2>Adult and other CQC-registered services</h2>
<p>If you work in a service registered with the Care Quality Commission in England, such as a care home, home care agency or supported living service, <a href="https://www.legislation.gov.uk/uksi/2014/2936/regulation/18">regulation 18 of the Health and Social Care Act 2008 (Regulated Activities) Regulations 2014</a> applies. It requires that staff receive <strong>such appropriate support, training, professional development, supervision and appraisal as is necessary to enable them to carry out the duties they are employed to perform</strong>.</p>
<p>CQC\'s guidance on regulation 18 makes clear that supervision should be regular and planned, not an occasional afterthought, and inspectors routinely ask staff whether they receive it. Similar expectations apply in Wales, Scotland and Northern Ireland under their own care standards and inspectorates.</p>
<h2>How often should supervision happen?</h2>
<p>The regulations do not fix a single national frequency for every worker. Instead, your employer must decide what is necessary for your role and put it in policy. In practice:</p>
<ul>
<li>Your organisation\'s <strong>supervision policy</strong> should state how often you are entitled to formal supervision. Ask to see it if you have not.</li>
<li>New starters, staff in induction (for example, completing the Care Certificate) and staff working with complex or high-risk situations should normally be supervised more often.</li>
<li>Commissioners and inspectors expect supervision to be <strong>regular, recorded and two-way</strong>, with agreed actions followed up.</li>
</ul>
<h2>What good supervision covers</h2>
<ul>
<li><strong>Practice and the people you support:</strong> reviewing your work, risk, safeguarding concerns and anything you are unsure about</li>
<li><strong>Wellbeing:</strong> workload, stress, the emotional impact of the work, and any support you need after difficult incidents</li>
<li><strong>Development:</strong> training needs, qualifications, career plans and feedback on your performance</li>
<li><strong>Accountability:</strong> clear, recorded decisions and actions, with a copy of the record available to you</li>
</ul>
<p>Good supervision is a conversation, not a telling-off. Disciplinary matters should be dealt with under a separate procedure, and a supervision session should never be turned into a disciplinary hearing without warning.</p>
<h2>What to do if you are not getting supervision</h2>
<ol>
<li><strong>Check the policy and keep a note.</strong> Record when your sessions were cancelled or simply never arranged.</li>
<li><strong>Ask in writing.</strong> A short, polite email to your manager asking for supervision to be scheduled creates a record and often solves the problem.</li>
<li><strong>Escalate internally.</strong> If nothing changes, raise it with a more senior manager, or the registered manager or responsible individual for your service.</li>
<li><strong>Use the grievance procedure</strong> if you are still not being supported, especially if the lack of supervision is affecting your practice or wellbeing.</li>
<li><strong>Tell the regulator if needed.</strong> You can raise concerns with CQC or, for children\'s homes, with Ofsted. Workers who raise concerns about care standards in the public interest are protected from dismissal and detriment by the Public Interest Disclosure Act 1998. See the government guidance on <a href="https://www.gov.uk/whistleblowing">whistleblowing</a>.</li>
</ol>
<p>Remember that missing supervision is not just your problem. If staff are unsupported, the quality and safety of care usually suffers, which is exactly why the regulations exist.</p>
<h2>Where to get help</h2>
<ul>
<li><strong>Your registered manager or responsible individual</strong>, who is accountable to the regulator for staff support.</li>
<li><strong>Your trade union</strong>, which can raise supervision failures collectively as well as individually.</li>
<li><strong>CQC or Ofsted</strong> to raise concerns about a registered service. For Ofsted, see <a href="https://www.gov.uk/government/organisations/ofsted">gov.uk/government/organisations/ofsted</a>.</li>
<li><strong>Acas helpline</strong> on 0300 123 1100 for advice on grievances and how to raise concerns safely.</li>
<li><strong>Citizens Advice</strong> if the problem is affecting your employment more widely.</li>
</ul>', 'published', '2027-07-30', NOW())
  ON DUPLICATE KEY UPDATE title = VALUES(title), meta_description = VALUES(meta_description), summary = VALUES(summary), key_legislation = VALUES(key_legislation), body_html = VALUES(body_html);

INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('placement-plan', 'Placement Plan', 'A complete placement plan covering the child\'s details, legal status, delegated authority and consents, health, education, identity, family time, risks and daily living. Ready to complete within the first days of a placement and review alongside the statutory care plan.', 'Reg 5, Care Planning, Placement and Case Review (England) Regulations 2010; Reg 14, Children\'s Homes (England) Regulations 2015', 'ofsted', 'care-planning', 'docx', 'placement-plan.docx', 39742, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('behaviour-support-plan', 'Behaviour Support Plan (PBS)', 'A positive behaviour support plan structured around understanding the behaviour and primary, secondary and reactive strategies, with post-incident repair. Includes a ready-to-print ABC (Antecedent–Behaviour–Consequence) recording sheet.', 'Regs 11, 20 & 35, Children\'s Homes (England) Regulations 2015', 'ofsted', 'care-planning', 'docx', 'behaviour-support-plan.docx', 39103, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('physical-intervention-record', 'Physical Intervention Record', 'A restraint record capturing everyone involved, de-escalation attempted, the technique and duration, injuries, effectiveness, the child\'s views and management sign-off. Built around the 48-hour and 5-day requirements of Regulation 35.', 'Reg 35, Children\'s Homes (England) Regulations 2015', 'ofsted', 'safeguarding', 'docx', 'physical-intervention-record.docx', 38946, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('missing-from-care-record', 'Missing from Care Record & Return Home Interview', 'A two-part record for missing episodes: risk information, police reference, a timeline of actions and return details, followed by an independent return home interview form with suggested questions and an action plan.', 'Statutory guidance on children who run away or go missing from home or care (DfE, 2014); Reg 40, Children\'s Homes (England) Regulations 2015', 'ofsted', 'safeguarding', 'docx', 'missing-from-care-record.docx', 39171, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('key-work-session-log', 'Key Work Session Log', 'A structured log for one-to-one key work sessions linking each session to care plan objectives, recording the child\'s views in their own words and tracking agreed actions to the next session.', 'Quality Standards (Regs 6–14), Children\'s Homes (England) Regulations 2015', 'ofsted', 'recording', 'docx', 'key-work-session-log.docx', 37984, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('reg-44-visit-pack', 'Reg 44 Independent Visitor Preparation Pack', 'Everything the independent person needs for a monthly Regulation 44 visit: a document sampling checklist, suggested questions for children, staff and the manager, observation prompts and a report structure focused on the two required opinions.', 'Reg 44, Children\'s Homes (England) Regulations 2015', 'ofsted', 'quality-audit', 'docx', 'reg-44-visit-pack.docx', 39721, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('reg-45-quality-review', 'Reg 45 Quality of Care Review', 'A six-monthly quality of care review structured around the Reg 45(2) matters: quality of care data and Quality Standards self-assessment, children\'s feedback and opinions, complaint actions and an improvement plan.', 'Reg 45, Children\'s Homes (England) Regulations 2015', 'ofsted', 'quality-audit', 'docx', 'reg-45-quality-review.docx', 39173, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('daily-log-template', 'Daily Log', 'A daily recording template with built-in prompts for factual, non-judgemental, child-focused recording across the whole day, including positives as well as concerns. Written on the basis that the child may read it.', 'Reg 36 & Schedule 3, Children\'s Homes (England) Regulations 2015', 'ofsted', 'recording', 'docx', 'daily-log-template.docx', 38214, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('handover-sheet', 'Shift Handover Sheet', 'A shift-change handover covering each child\'s day, medication, appointments, incidents, safeguarding updates, money, vehicles and outstanding tasks, signed by both the outgoing and incoming senior.', 'Reg 13 (leadership and management), Children\'s Homes (England) Regulations 2015', 'ofsted', 'recording', 'docx', 'handover-sheet.docx', 38067, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('friendship-associates-log', 'Friendship & Associates Log', 'A running log of each child\'s friends and associates on and offline, with prompts for exploitation warning signs and a clear route into safeguarding action. Supports missing episode responses and contextual safeguarding.', 'Reg 12 (protection of children), Children\'s Homes (England) Regulations 2015', 'ofsted', 'safeguarding', 'docx', 'friendship-associates-log.docx', 38057, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('young-persons-guide-skeleton', 'Young Person\'s Guide (Skeleton)', 'A child-friendly skeleton for your children\'s guide, with thirteen ready-made headings from \'Welcome\' to \'Important numbers\' and guidance on what to write in each. Adapt the language to the ages and needs of the children you care for.', 'Children\'s guide requirements, Children\'s Homes (England) Regulations 2015 and the Guide to the Regulations', 'ofsted', 'care-planning', 'docx', 'young-persons-guide-skeleton.docx', 38325, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('person-centred-care-plan', 'Person-Centred Care Plan', 'A full person-centred care plan: about me, communication, consent and capacity, and twelve care domains each recording what the person can do, the support they want and the outcome being worked towards, with a review record.', 'Regs 9 & 11, Health and Social Care Act 2008 (Regulated Activities) Regulations 2014', 'cqc', 'care-planning', 'docx', 'person-centred-care-plan.docx', 39292, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('one-page-profile', 'One-Page Profile', 'The classic one-page profile: what people appreciate about me, what is important to me, and how best to support me — with hints that push for specific, personal detail a stranger could act on.', 'Regs 9 & 10, Health and Social Care Act 2008 (Regulated Activities) Regulations 2014', 'cqc', 'care-planning', 'docx', 'one-page-profile.docx', 37771, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('mca-capacity-assessment', 'MCA Capacity Assessment', 'A decision-specific mental capacity assessment working through the two-stage test: the diagnostic test and the four functional elements (understand, retain, use or weigh, communicate), with the supported decision-making steps evidenced first.', 'Mental Capacity Act 2005 ss.1–3; Reg 11, HSCA 2008 (Regulated Activities) Regulations 2014', 'cqc', 'care-planning', 'docx', 'mca-capacity-assessment.docx', 39004, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('best-interests-decision-record', 'Best Interests Decision Record', 'A section 4 best interests record with the full statutory checklist, a consultation table, an options comparison including less restrictive alternatives, and the decision with rationale and review arrangements.', 'Mental Capacity Act 2005 s.4', 'cqc', 'care-planning', 'docx', 'best-interests-decision-record.docx', 38795, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('dols-application-tracker', 'DoLS Application Tracker', 'A spreadsheet tracker for DoLS applications: urgent and standard authorisations, supervisory body, status, expiry and review dates, conditions and RPR details, with a status key sheet and dropdown validation built in.', 'Mental Capacity Act 2005 Schedule A1 (DoLS); Reg 13, HSCA 2008 (Regulated Activities) Regulations 2014', 'cqc', 'safeguarding', 'xlsx', 'dols-application-tracker.xlsx', 8912, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('mar-audit-tool', 'MAR Audit Tool', 'A twenty-question MAR chart audit with Yes / No / N/A columns covering signatures, gaps, PRN protocols, controlled drugs, storage temperatures and staff competency, feeding into an action plan.', 'Reg 12(2)(g) (safe management of medicines), HSCA 2008 (Regulated Activities) Regulations 2014', 'cqc', 'medication', 'docx', 'mar-audit-tool.docx', 38941, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('medication-error-record', 'Medication Error Record', 'A no-blame medication error record: what happened, immediate safety checks, GP / NHS 111 advice, notifications including CQC and safeguarding, and a root-cause reflection with actions to prevent recurrence.', 'Reg 12, HSCA 2008 (Regulated Activities) Regulations 2014; Reg 18, CQC (Registration) Regulations 2009', 'cqc', 'medication', 'docx', 'medication-error-record.docx', 38684, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('incident-accident-form', 'Incident / Accident Form', 'An incident and accident form for residents, staff and visitors with injuries and treatment, a structured RIDDOR reportability check, notification checklist and manager review for learning.', 'Regs 12 & 17, HSCA 2008 (Regulated Activities) Regulations 2014; RIDDOR 2013', 'cqc', 'recording', 'docx', 'incident-accident-form.docx', 38654, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('complaints-log', 'Complaints Log', 'A single oversight log for all complaints — including verbal ones — tracking acknowledgement, investigation, outcome, response and learning, with recommended timescales and escalation routes included.', 'Reg 16 (receiving and acting on complaints), HSCA 2008 (Regulated Activities) Regulations 2014', 'cqc', 'quality-audit', 'docx', 'complaints-log.docx', 38012, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('duty-of-candour-record', 'Duty of Candour Record', 'A step-by-step Regulation 20 record: the notifiable safety incident, the verbal notification and apology, the written follow-up, sharing of investigation results and the audit trail CQC expects to see.', 'Reg 20 (duty of candour), HSCA 2008 (Regulated Activities) Regulations 2014', 'cqc', 'quality-audit', 'docx', 'duty-of-candour-record.docx', 38515, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('statement-of-purpose-skeleton', 'Statement of Purpose (Skeleton)', 'A ten-section skeleton covering the Schedule 3 matters: provider details, aims and objectives, regulated activities, needs met, locations, staffing, the registered manager and contact details, with guidance under each heading.', 'Reg 12 & Schedule 3, CQC (Registration) Regulations 2009', 'cqc', 'quality-audit', 'docx', 'statement-of-purpose-skeleton.docx', 38414, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('service-user-guide-skeleton', 'Service User Guide (Skeleton)', 'A plain-English service user guide skeleton with twelve headings from \'Welcome\' to \'Useful contacts\', each with guidance on content, adaptable to residential or home care settings and accessible formats.', 'Regs 9 & 17, HSCA 2008 (Regulated Activities) Regulations 2014; Accessible Information Standard', 'cqc', 'care-planning', 'docx', 'service-user-guide-skeleton.docx', 38372, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('supervision-record-staff', 'Supervision Record — Staff', 'A one-to-one supervision record for care staff covering wellbeing, caseload and key work, safeguarding, performance, development and agreed actions, with review of the previous session\'s actions built in.', 'Reg 33, Children\'s Homes (England) Regulations 2015; Reg 18(2)(a), HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'hr-staffing', 'docx', 'supervision-record-staff.docx', 38305, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('supervision-record-manager', 'Supervision Record — Manager', 'A supervision record for the registered manager, led by the responsible or nominated individual: safeguarding and incident oversight, quality and compliance, staffing, resources and the manager\'s own wellbeing and development.', 'Reg 33, Children\'s Homes (England) Regulations 2015; Reg 18(2)(a), HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'hr-staffing', 'docx', 'supervision-record-manager.docx', 38263, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('team-meeting-agenda-minutes', 'Team Meeting Agenda & Minutes', 'A combined agenda and minutes template with a twelve-item standing agenda, an action log, and a read-and-understood sign sheet for staff who missed the meeting.', 'Reg 13, Children\'s Homes (England) Regulations 2015; Reg 17, HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'hr-staffing', 'docx', 'team-meeting-agenda-minutes.docx', 38123, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('reflective-practice-log', 'Reflective Practice Log', 'A reflection template working through all six stages of Gibbs\' reflective cycle with prompts at each stage, linking the reflection into supervision and the staff member\'s development plan.', 'Care Certificate Standard 2; Reg 18, HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'hr-staffing', 'docx', 'reflective-practice-log.docx', 38182, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('induction-checklist-care-certificate', 'Induction Checklist (Care Certificate)', 'A two-part induction checklist: first-week essentials from fire safety to key policies, then sign-off against each of the 15 Care Certificate standards with assessor initials and a 12-week target.', 'The Care Certificate (Skills for Care / Health Education England); Reg 18 & 19, HSCA 2008 (Regulated Activities) Regulations 2014; Reg 33, CHR 2015', 'both', 'hr-staffing', 'docx', 'induction-checklist-care-certificate.docx', 38751, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('safer-recruitment-checklist', 'Safer Recruitment Checklist', 'A start-to-finish safer recruitment checklist for each appointment — advert wording, application and gap checking, enhanced DBS with barred list, verified references, overseas checks and induction — filed as evidence in the staff record.', 'Schedule 2, Children\'s Homes (England) Regulations 2015; Reg 19 & Schedule 3, HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'hr-staffing', 'docx', 'safer-recruitment-checklist.docx', 38710, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('audit-schedule-annual', 'Annual Audit Schedule', 'A landscape 12-month audit planner pre-loaded with nineteen audit areas and suggested frequencies, from MAR charts to unannounced night visits, with a simple planned / completed marking key.', 'Reg 45, Children\'s Homes (England) Regulations 2015; Reg 17 (good governance), HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'quality-audit', 'docx', 'audit-schedule-annual.docx', 38597, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);
INSERT INTO templates (slug, title, description, supports, regulator, category, format, filename, filesize, status, last_reviewed, review_due) VALUES ('risk-assessment-5x5', 'Risk Assessment (5x5 Matrix)', 'A general risk assessment template with a colour 5x5 likelihood-by-severity matrix, full scoring key and rating bands, hazard table with residual scoring, and a review record.', 'Management of Health and Safety at Work Regulations 1999; Reg 12, CHR 2015; Reg 12, HSCA 2008 (Regulated Activities) Regulations 2014', 'both', 'safeguarding', 'docx', 'risk-assessment-5x5.docx', 38915, 'published', '2026-07-01', '2027-07-30')
  ON DUPLICATE KEY UPDATE title = VALUES(title), description = VALUES(description), supports = VALUES(supports), filesize = VALUES(filesize);

INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ABC', 'Antecedent, Behaviour, Consequence', 'A recording method that logs what happened before, during and after an incident to help understand the triggers for behaviour.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ACEs', 'Adverse Childhood Experiences', 'Stressful or traumatic events in childhood, such as abuse or household dysfunction, linked to poorer health and life outcomes.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ADASS', 'Association of Directors of Adult Social Services', 'The membership body for directors of adult social services in England, which influences national policy.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ADCS', 'Association of Directors of Children\'s Services', 'The membership body for directors of children\'s services in England, which influences national policy.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ADHD', 'Attention Deficit Hyperactivity Disorder', 'A neurodevelopmental condition involving persistent inattention, hyperactivity and impulsivity that affects daily life.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ADLs', 'Activities of Daily Living', 'Everyday self-care tasks such as washing, dressing, eating and moving about, used to assess how much support a person needs.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ADM', 'Agency Decision Maker', 'The senior officer in an adoption or fostering agency who makes formal decisions, such as whether a child should be placed for adoption.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('AMHP', 'Approved Mental Health Professional', 'A specially trained professional, often a social worker, who co-ordinates Mental Health Act assessments and can apply for a person to be detained.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('AP', 'Alternative Provision', 'Education arranged for pupils who cannot attend mainstream school, for example because of exclusion or illness.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ASD', 'Autism Spectrum Disorder', 'A lifelong neurodevelopmental condition affecting how a person communicates, interacts and experiences the world.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ASYE', 'Assessed and Supported Year in Employment', 'A supported first year in practice for newly qualified social workers, with reduced caseloads and regular assessment.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('BASW', 'British Association of Social Workers', 'The professional association for social workers across the UK, which publishes the profession\'s code of ethics.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('BIA', 'Best Interests Assessor', 'A trained professional who assesses whether a deprivation of liberty is in a person\'s best interests under the DoLS scheme.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CAFCASS', 'Children and Family Court Advisory and Support Service', 'The organisation that represents children\'s interests in family court proceedings in England.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CAMHS', 'Child and Adolescent Mental Health Services', 'NHS services that assess and treat children and young people with emotional, behavioural or mental health difficulties.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CAO', 'Child Arrangements Order', 'A court order deciding who a child lives with, spends time with or otherwise has contact with.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CCE', 'Child Criminal Exploitation', 'Abuse where a child is coerced or manipulated into criminal activity, such as county lines drug dealing.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CDOP', 'Child Death Overview Panel', 'The multi-agency panel that reviews the deaths of all children in an area to identify learning and prevent future deaths.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CEOP', 'Child Exploitation and Online Protection Command', 'The National Crime Agency command that tackles online child sexual abuse and exploitation and runs a public reporting service.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CHC', 'Continuing Healthcare', 'NHS-funded care for adults whose long-term care needs arise primarily from health needs, covering the full cost of their care.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CIC', 'Child in Care', 'An alternative term for a looked-after child, used by many local authorities and often preferred by young people.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CIN', 'Child in Need', 'A child assessed under section 17 of the Children Act 1989 as needing extra services to achieve a reasonable standard of health or development.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CLA', 'Child Looked After', 'The term now preferred by many local authorities for a child in the care of the local authority, replacing LAC.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CME', 'Children Missing Education', 'Children of compulsory school age who are not registered at a school and are not receiving suitable education elsewhere.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CoP', 'Court of Protection', 'The court that makes decisions about the property, welfare and finances of people who lack mental capacity.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CoramBAAF', 'Coram British Association for Adoption and Fostering', 'The membership organisation that provides guidance, forms and research for adoption, fostering and kinship care.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('COSHH', 'Control of Substances Hazardous to Health', 'Regulations requiring employers to control exposure to hazardous substances such as cleaning chemicals.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CP', 'Child Protection', 'Work carried out to protect a child who is suffering, or is likely to suffer, significant harm.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CPN', 'Community Psychiatric Nurse', 'A mental health nurse who supports people living in the community rather than in hospital.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CPP', 'Child Protection Plan', 'A multi-agency plan setting out the actions needed to keep a child safe after a child protection conference decides they are at risk of significant harm.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CQC', 'Care Quality Commission', 'The independent regulator of health and adult social care services in England.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CSA', 'Child Sexual Abuse', 'Forcing or enticing a child to take part in sexual activities, whether or not the child is aware of what is happening.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CSE', 'Child Sexual Exploitation', 'A form of sexual abuse where a child is coerced, manipulated or deceived into sexual activity, often in exchange for something they want or need.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CSPR', 'Child Safeguarding Practice Review', 'A statutory review held after a child dies or is seriously harmed and abuse or neglect is known or suspected, to identify improvements to practice.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CTO', 'Community Treatment Order', 'An order allowing a patient detained under the Mental Health Act to be treated in the community subject to conditions, with a power of recall to hospital.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CWD', 'Children with Disabilities', 'A common name for the social work teams and services that support disabled children and their families.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('CYP', 'Children and Young People', 'A general term covering children and young people, usually from birth up to age 18 or 25.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DASH', 'Domestic Abuse, Stalking and Harassment and Honour-Based Violence', 'A standard checklist used to assess the level of risk faced by victims of domestic abuse.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DBS', 'Disclosure and Barring Service', 'The body that carries out criminal record checks and maintains lists of people barred from working with children or vulnerable adults.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DDP', 'Dyadic Developmental Psychotherapy', 'A therapy and parenting approach for children affected by trauma and attachment difficulties, focused on building safe relationships.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DHR', 'Domestic Homicide Review', 'A statutory review held after a death caused by domestic abuse to learn lessons and improve how agencies protect victims.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DNACPR', 'Do Not Attempt Cardiopulmonary Resuscitation', 'A recorded clinical decision that CPR should not be attempted if a person\'s heart or breathing stops.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DoC', 'Duty of Candour', 'The legal duty on care providers to be open and honest with people, and apologise, when something goes wrong with their care.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DoLS', 'Deprivation of Liberty Safeguards', 'Legal safeguards ensuring that people in hospitals and care homes who lack capacity are only deprived of their liberty when it is authorised and in their best interests.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DPA', 'Data Protection Act 2018', 'The UK law, alongside UK GDPR, that governs how organisations must handle personal data.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DSL', 'Designated Safeguarding Lead', 'The senior member of school or college staff responsible for safeguarding and child protection, including making referrals.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DST', 'Decision Support Tool', 'The national form used by a multidisciplinary team to decide whether someone is eligible for NHS Continuing Healthcare.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('DWP', 'Department for Work and Pensions', 'The government department responsible for welfare benefits and pensions.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EBSA', 'Emotionally Based School Avoidance', 'Difficulty attending school caused by anxiety or emotional distress rather than truancy.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ECHR', 'European Convention on Human Rights', 'The international treaty protecting rights such as liberty, family life and freedom from inhuman treatment, given effect in UK law by the Human Rights Act.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EHA', 'Early Help Assessment', 'An assessment used to identify a child\'s and family\'s needs early so support can be offered before problems escalate.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EHC', 'Education, Health and Care', 'The combined assessment process that can lead to an EHC plan for a child or young person with special educational needs.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EHCP', 'Education, Health and Care Plan', 'A legal document for children and young people up to 25 setting out their special educational needs and the support they must receive.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EHE', 'Elective Home Education', 'A parent\'s choice to educate their child at home instead of sending them to school.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ELSA', 'Emotional Literacy Support Assistant', 'A school teaching assistant trained to support pupils with their emotional development and wellbeing.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('eMAR', 'Electronic Medication Administration Record', 'A digital version of the medication administration record used to log medicines given in care settings.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EOTAS', 'Education Otherwise Than At School', 'Education arranged by a local authority for a child who cannot attend school, delivered outside a school setting.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EPA', 'Enduring Power of Attorney', 'An older form of power of attorney, made before October 2007, covering property and financial affairs; replaced by the LPA.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EWO', 'Education Welfare Officer', 'A local authority officer who works with schools and families to improve school attendance.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EYFS', 'Early Years Foundation Stage', 'The statutory framework setting standards for the learning, development and care of children from birth to age five.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('EYP', 'Early Years Practitioner', 'A person qualified to work with young children in early years settings such as nurseries.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('FDAC', 'Family Drug and Alcohol Court', 'A problem-solving family court that supports parents in care proceedings to address substance misuse and keep their children where possible.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('FGC', 'Family Group Conference', 'A family-led meeting in which the wider family makes a plan to keep a child safe and meet their needs.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('FGM', 'Female Genital Mutilation', 'The illegal practice of partially or totally removing or injuring a girl\'s or woman\'s genitalia for non-medical reasons.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('FNC', 'Funded Nursing Care', 'An NHS payment towards the nursing care element of a place in a nursing home for people not eligible for full Continuing Healthcare.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('FOI', 'Freedom of Information', 'The legal right, under the Freedom of Information Act 2000, to request recorded information held by public bodies.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('GDD', 'Global Developmental Delay', 'A significant delay in two or more areas of a young child\'s development, such as speech, movement or learning.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('GDPR', 'General Data Protection Regulation', 'The data protection framework, retained in UK law as UK GDPR, setting rules for how personal data must be processed.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('GP', 'General Practitioner', 'A family doctor providing general medical care in the community and referrals to specialist services.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('HCPC', 'Health and Care Professions Council', 'The regulator for professions such as occupational therapists, paramedics and speech and language therapists.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('HI', 'Hearing Impairment', 'A special educational needs category covering deafness or partial hearing loss that affects a child\'s learning.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('HRA', 'Human Rights Act 1998', 'The law that makes rights from the European Convention on Human Rights enforceable in UK courts.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('HSB', 'Harmful Sexual Behaviour', 'Sexual behaviour by a child or young person that is developmentally inappropriate and may be harmful to themselves or others.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('HSE', 'Health and Safety Executive', 'The national regulator for workplace health and safety in Great Britain.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICB', 'Integrated Care Board', 'The NHS body responsible for planning and funding most NHS services in a local area.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICMP', 'Individual Crisis Management Plan', 'A personalised plan in residential childcare describing how staff should respond when a specific child is in crisis, including any agreed physical intervention.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICO', 'Information Commissioner\'s Office', 'The UK regulator for data protection and information rights, to which serious data breaches must be reported.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICO', 'Interim Care Order', 'A temporary court order placing a child in local authority care while care proceedings are ongoing.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICPC', 'Initial Child Protection Conference', 'The first multi-agency meeting, held after section 47 enquiries, that decides whether a child needs a child protection plan.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ICS', 'Integrated Care System', 'A partnership of NHS organisations, councils and others responsible for planning health and care services for a local population.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IDVA', 'Independent Domestic Violence Advisor', 'A trained specialist who supports victims of domestic abuse at highest risk of serious harm or murder.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IEP', 'Individual Education Plan', 'A school-level plan setting targets and support strategies for a pupil with additional learning needs.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IFA', 'Independent Fostering Agency', 'A non-local-authority organisation that recruits, trains and supports foster carers and places children with them.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IMCA', 'Independent Mental Capacity Advocate', 'An advocate appointed to represent a person who lacks capacity and has no family or friends to consult about serious decisions.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IMHA', 'Independent Mental Health Advocate', 'An advocate who helps patients detained or treated under the Mental Health Act understand and exercise their rights.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IPC', 'Infection Prevention and Control', 'The practices, such as hand hygiene and cleaning, used to stop infections spreading in care settings.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('IRO', 'Independent Reviewing Officer', 'An independent social worker who chairs a looked-after child\'s reviews and checks the care plan is being followed.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ISVA', 'Independent Sexual Violence Advisor', 'A trained specialist who supports victims of sexual violence through the criminal justice process and beyond.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ISW', 'Independent Social Worker', 'A registered social worker commissioned independently, often to provide expert assessments in court proceedings.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('KCSIE', 'Keeping Children Safe in Education', 'The statutory safeguarding guidance that all schools and colleges in England must follow.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LA', 'Local Authority', 'The local council responsible for services including children\'s and adults\' social care and education.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LAC', 'Looked After Child', 'A child who is in the care of the local authority, whether under a care order or a voluntary arrangement.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LADO', 'Local Authority Designated Officer', 'The council officer who manages allegations against adults who work or volunteer with children.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LD', 'Learning Disability', 'A reduced intellectual ability and difficulty with everyday activities that starts in childhood and lasts throughout life.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LeDeR', 'Learning from Lives and Deaths', 'The NHS programme that reviews the deaths of people with a learning disability and autistic people to improve care.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LOLER', 'Lifting Operations and Lifting Equipment Regulations 1998', 'The law requiring lifting equipment, such as hoists in care settings, to be safe, maintained and regularly inspected.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LPA', 'Lasting Power of Attorney', 'A legal document letting a person appoint someone to make decisions about their finances or health and welfare if they lose capacity.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('LPS', 'Liberty Protection Safeguards', 'The scheme created by the Mental Capacity (Amendment) Act 2019 intended to replace DoLS, though its implementation has been shelved.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MAPPA', 'Multi-Agency Public Protection Arrangements', 'The framework through which police, probation and prisons manage the risk posed by violent and sexual offenders.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MAR', 'Medication Administration Record', 'The document used in care settings to record every dose of medication given, refused or omitted.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MARAC', 'Multi-Agency Risk Assessment Conference', 'A regular multi-agency meeting that shares information and plans safety actions for domestic abuse victims at high risk.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MASH', 'Multi-Agency Safeguarding Hub', 'A team where police, social care, health and other agencies share information to decide how to respond to safeguarding concerns.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MCA', 'Mental Capacity Act 2005', 'The law setting out how to assess whether a person aged 16 or over can make their own decisions and how to make best-interests decisions for those who cannot.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MDT', 'Multi-Disciplinary Team', 'A group of professionals from different disciplines who work together on a person\'s assessment, care and treatment.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MFH', 'Missing From Home', 'The status of a child or adult whose whereabouts are unknown and who is considered at risk, triggering agreed reporting procedures.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MHA', 'Mental Health Act 1983', 'The law governing the assessment, detention and treatment of people with a mental disorder in England and Wales.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MLD', 'Moderate Learning Difficulties', 'A special educational needs category for pupils whose attainment is well below expected levels across most areas of the curriculum.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('MUST', 'Malnutrition Universal Screening Tool', 'A screening tool used to identify adults who are malnourished or at risk of malnutrition.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NAI', 'Non-Accidental Injury', 'An injury to a child that is judged to have been inflicted rather than caused by accident, raising child protection concerns.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NEET', 'Not in Education, Employment or Training', 'A young person, usually aged 16 to 24, who is not in education, employment or training.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NEWS2', 'National Early Warning Score 2', 'A standard NHS scoring system that uses vital signs to spot adults whose health is deteriorating.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NHS', 'National Health Service', 'The UK\'s publicly funded health service, free at the point of use.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NRM', 'National Referral Mechanism', 'The national framework for identifying and supporting victims of modern slavery and human trafficking.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('NSPCC', 'National Society for the Prevention of Cruelty to Children', 'A leading children\'s charity that runs child protection services, research and the Childline helpline.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('OFSTED', 'Office for Standards in Education, Children\'s Services and Skills', 'The inspectorate that regulates and inspects schools, early years settings and children\'s social care services, including children\'s homes.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('OT', 'Occupational Therapist', 'A health professional who helps people overcome barriers to everyday activities, often by recommending equipment, adaptations or new techniques.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PA', 'Personal Adviser', 'The worker who supports a care leaver from age 16 to 25, helping with their pathway plan, housing, education and independence.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PACE', 'Playfulness, Acceptance, Curiosity, Empathy', 'A therapeutic parenting approach, developed by Dan Hughes, used to build trust and emotional connection with children who have experienced trauma.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PACE', 'Police and Criminal Evidence Act 1984', 'The law governing police powers such as arrest, detention and interviews, including the requirement for an appropriate adult for children and vulnerable adults.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PBS', 'Positive Behaviour Support', 'A person-centred approach to understanding behaviour that challenges and reducing it by improving quality of life rather than punishing.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PEEP', 'Personal Emergency Evacuation Plan', 'An individual plan describing how a person who cannot evacuate a building unaided will be helped to safety in an emergency.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PEG', 'Percutaneous Endoscopic Gastrostomy', 'A feeding tube placed through the abdominal wall into the stomach for people who cannot eat or drink safely by mouth.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PEP', 'Personal Education Plan', 'The education part of a looked-after child\'s care plan, reviewed each term with the school and social worker.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PIP', 'Personal Independence Payment', 'A welfare benefit for people with a long-term health condition or disability that affects daily living or mobility.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PLAC', 'Previously Looked After Child', 'A child who was in care but left through adoption, a special guardianship order or a child arrangements order, and remains entitled to certain support.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PLO', 'Public Law Outline', 'The framework and pre-proceedings process courts and local authorities must follow in care proceedings.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PMLD', 'Profound and Multiple Learning Disabilities', 'A severe learning disability combined with other significant needs, such as physical disabilities or sensory impairments, requiring high levels of support.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('POVA', 'Protection of Vulnerable Adults', 'An older term, and former vetting scheme, for the arrangements to safeguard adults at risk of abuse or neglect.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PPE', 'Personal Protective Equipment', 'Items such as gloves, aprons and masks worn to protect against infection or other hazards.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PR', 'Parental Responsibility', 'The legal rights, duties and authority a parent or other person has for a child and the child\'s property.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PRN', 'Pro Re Nata', 'Latin for \'as required\'; medication prescribed to be given only when needed, such as for pain, rather than at set times.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PRU', 'Pupil Referral Unit', 'A type of school that educates children who cannot attend mainstream school, often following exclusion.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('PSHE', 'Personal, Social, Health and Economic Education', 'The school subject in which pupils learn about health, relationships, safety and living in the wider world.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('QS', 'Quality Standards', 'The nine standards in the Children\'s Homes (England) Regulations 2015 that describe the outcomes children\'s homes must achieve.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RCCW', 'Residential Child Care Worker', 'A practitioner who cares for children living in children\'s homes, supporting their daily lives, development and wellbeing.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RCPC', 'Review Child Protection Conference', 'A follow-up multi-agency meeting that reviews a child protection plan and decides whether it is still needed.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('Reg 40', 'Regulation 40, Children\'s Homes (England) Regulations 2015', 'The requirement to notify Ofsted and other relevant agencies of serious events, such as a child\'s death, serious injury or allegation of abuse.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('Reg 44', 'Regulation 44, Children\'s Homes (England) Regulations 2015', 'The requirement for an independent person to visit a children\'s home each month and report on the safety and wellbeing of the children.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('Reg 45', 'Regulation 45, Children\'s Homes (England) Regulations 2015', 'The requirement for a children\'s home to review the quality of its care at least every six months and produce a report.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('ReSPECT', 'Recommended Summary Plan for Emergency Care and Treatment', 'A personalised plan recording a person\'s preferences and clinical recommendations for their care in a future emergency.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RHI', 'Return Home Interview', 'An independent interview offered to a child after a missing episode to understand why they went missing and what happened.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RI', 'Responsible Individual', 'The person appointed by a provider to supervise the management of a registered service and represent the organisation to the regulator.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RIDDOR', 'Reporting of Injuries, Diseases and Dangerous Occurrences Regulations 2013', 'The law requiring employers to report specified workplace deaths, injuries, illnesses and near misses to the Health and Safety Executive.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RM', 'Registered Manager', 'The person registered with the regulator as responsible for the day-to-day management of a care service.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RSE', 'Relationships and Sex Education', 'The statutory school subject covering healthy relationships, consent and, in secondary schools, sex education.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('RSW', 'Residential Support Worker', 'A member of staff in a residential home who provides day-to-day care and support to the people living there.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('s.117', 'Section 117, Mental Health Act 1983', 'The duty on the NHS and local authorities to provide free aftercare to people who have been detained under certain sections of the Mental Health Act.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('s.17', 'Section 17, Children Act 1989', 'The legal duty on local authorities to provide services to safeguard and promote the welfare of children in need.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('s.20', 'Section 20, Children Act 1989', 'Voluntary accommodation of a child by the local authority with parental consent, without a court order.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('s.31', 'Section 31, Children Act 1989', 'The provision under which a court can make a care or supervision order if a child is suffering or likely to suffer significant harm.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('s.47', 'Section 47, Children Act 1989', 'The duty on a local authority to make enquiries when it suspects a child is suffering, or is likely to suffer, significant harm.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SAB', 'Safeguarding Adults Board', 'The statutory multi-agency board in each local authority area that oversees adult safeguarding arrangements under the Care Act 2014.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SALT', 'Speech and Language Therapist', 'A health professional who assesses and treats communication difficulties and swallowing problems.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SAR', 'Safeguarding Adults Review', 'A statutory review held when an adult with care and support needs dies or is seriously harmed and abuse or neglect is suspected, to learn lessons.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SAR', 'Subject Access Request', 'A request under data protection law by which a person can ask an organisation for copies of the personal data it holds about them.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SBAR', 'Situation, Background, Assessment, Recommendation', 'A structured communication tool used to hand over concerns about a person\'s health clearly and quickly.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SDQ', 'Strengths and Difficulties Questionnaire', 'A short questionnaire used to screen children\'s emotional and behavioural wellbeing, completed annually for looked-after children.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SEMH', 'Social, Emotional and Mental Health', 'A special educational needs category for pupils whose emotional or mental health difficulties affect their behaviour and learning.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SENCO', 'Special Educational Needs Co-ordinator', 'The teacher in a school responsible for organising support for pupils with special educational needs.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SEND', 'Special Educational Needs and Disabilities', 'The umbrella term for learning difficulties or disabilities that make it harder for a child to learn than most children of the same age.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SENDIASS', 'Special Educational Needs and Disabilities Information, Advice and Support Service', 'The free, impartial service in each area that advises parents and young people about SEND rights and support.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SGO', 'Special Guardianship Order', 'A court order appointing a carer, often a relative, as a child\'s special guardian with enhanced parental responsibility until the child is 18.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SLCN', 'Speech, Language and Communication Needs', 'Difficulties with speaking, understanding language or communicating socially that affect a child\'s learning and relationships.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SoP', 'Statement of Purpose', 'The document every registered care service must have describing what it does, who it is for and how it delivers care.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SOVA', 'Safeguarding of Vulnerable Adults', 'An older umbrella term for the policies and procedures used to protect adults at risk from abuse and neglect.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SpLD', 'Specific Learning Difficulty', 'A difficulty affecting a particular aspect of learning, such as dyslexia, dyspraxia or dyscalculia, rather than general ability.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('STOMP', 'Stopping Over-Medication of People with a Learning Disability, Autism or Both', 'An NHS programme to reduce inappropriate use of psychotropic medication for people with a learning disability or autism.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SW', 'Social Worker', 'A registered professional who assesses need and risk and supports children, adults and families to improve their safety and wellbeing.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('SWE', 'Social Work England', 'The regulator that registers social workers in England and sets professional standards.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('TAC', 'Team Around the Child', 'A group of practitioners from different services who meet with the family to plan co-ordinated support for a child.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('TAF', 'Team Around the Family', 'A group of practitioners who work together with a family to deliver a co-ordinated early help plan.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('TILE', 'Task, Individual, Load, Environment', 'The four factors assessed when planning safe moving and handling of people or objects.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('UASC', 'Unaccompanied Asylum-Seeking Child', 'A child claiming asylum in the UK who is separated from their parents and is cared for by a local authority.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('UC', 'Universal Credit', 'The main means-tested welfare benefit for working-age people, replacing several older benefits.', 'adults');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('UTI', 'Urinary Tract Infection', 'An infection of the bladder or urinary system which, in older people, can cause sudden confusion or delirium.', 'health');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('VAWG', 'Violence Against Women and Girls', 'The umbrella term for crimes disproportionately affecting women and girls, including domestic abuse, sexual violence and stalking.', 'both');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('VI', 'Visual Impairment', 'A special educational needs category covering sight loss that affects a child\'s access to learning.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('VSH', 'Virtual School Head', 'The local authority officer responsible for promoting the educational achievement of looked-after and previously looked-after children.', 'education');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('WTSC', 'Working Together to Safeguard Children', 'The statutory guidance setting out how agencies in England must work together to safeguard and promote the welfare of children.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('YJS', 'Youth Justice Service', 'The local multi-agency service, formerly known as the youth offending team, that works with children who offend or are at risk of offending.', 'children');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('YOI', 'Young Offender Institution', 'A custodial establishment for young people sentenced or remanded by the courts.', 'legal');
INSERT INTO acronyms (acronym, full_term, meaning, sector) VALUES ('YOT', 'Youth Offending Team', 'The multi-agency team that supervises children who have offended and works to prevent reoffending; now often called the Youth Justice Service.', 'children');

INSERT INTO nmw_rates (band, label, hourly_rate, effective_from) VALUES ('nlw_21_over', 'National Living Wage (21 and over)', '12.21', '2025-04-01') ON DUPLICATE KEY UPDATE hourly_rate = VALUES(hourly_rate);
