INSERT INTO nmw_rates (band, label, hourly_rate, effective_from) VALUES ('apprentice', 'Apprentice rate', '6.40', '2024-04-01') ON DUPLICATE KEY UPDATE hourly_rate = VALUES(hourly_rate);

INSERT INTO settings (setting_key, setting_value) VALUES ('wtr_params', '{"weekly_limit":48,"daily_rest":11,"weekly_rest":24,"break_minutes":20,"break_trigger_hours":6,"night_limit":8}') ON DUPLICATE KEY UPDATE setting_value = setting_value;
INSERT INTO settings (setting_key, setting_value) VALUES ('hero_copy', '{"heading":"Practical tools for people who do the real work of care","lead":"Free calculators, templates and plain-English guidance for the UK social care workforce — children\'s homes and adult services, Ofsted and CQC."}') ON DUPLICATE KEY UPDATE setting_value = setting_value;
INSERT INTO settings (setting_key, setting_value) VALUES ('featured_tools', '["sleep-in-pay-checker","holiday-accrual-calculator","notification-decision-tool","acronym-decoder","training-matrix","body-map"]') ON DUPLICATE KEY UPDATE setting_value = setting_value;
INSERT INTO settings (setting_key, setting_value) VALUES ('maintenance_mode', '0') ON DUPLICATE KEY UPDATE setting_value = setting_value;
